  var FT = root.CALR_FULLTEXT = root.CALR_FULLTEXT || {};
  FT["ID-H049"] = {"id":"ID-H049","coverage":"full","language":"id","sourceName":"印度尼西亚官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"电子信息与交易法修正案","en":"Law No. 19 of 2016 on the Amendment to Law No. 11 of 2008 on Electronic Information and Transactions","orig":"Undang-Undang Nomor 19 Tahun 2016 tentang Perubahan atas Undang-Undang Nomor 11 Tahun 2008 tentang Informasi dan Transaksi Elektronik","id":"Undang-Undang Nomor 19 Tahun 2016 tentang Perubahan atas Undang-Undang Nomor 11 Tahun 2008 tentang Informasi dan Transaksi Elektronik","vi":"Luật số 19 năm 2016 về Sửa đổi Luật số 11 năm 2008 về Thông tin và Giao dịch Điện tử","th":"พระราชบัญญัติเลขที่ 19 ปี 2016 ว่าด้วยการแก้ไขพระราชบัญญัติเลขที่ 11 ปี 2008 ว่าด้วยข้อมูลและธุรกรรมอิเล็กทรอนิกส์","ms":"Akta No. 19 Tahun 2016 tentang Pindaan Akta No. 11 Tahun 2008 tentang Maklumat dan Transaksi Elektronik"},"level":"law","status":"active","issuingBody":"印度尼西亚官方发布渠道","promulgatedDate":"2016","completenessNote":"全文，共 7 条；取自《东盟法律分类》归档中的 MD 原件，逐字未改写。","country":"ID","countryName":"印度尼西亚","layer":"intl","articles":[{"id":"ID-H049-A1","no":1,"noLabel":{"zh":"第 1 条","en":"Article 1"},"text":{"id":"Setiap Orang yang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan yang melanggar kesusilaan sebagaimana dimaksud dalam Pasal 27 ayat (1) dipidana dengan pidana penjara paling lama 6 (enam) tahun dan/atau denda paling banyak Rp1.000.000.000,00 (satu miliar rupiah).\n\nSetiap Orang yang dengan sengaja dan tanpa hak menyebarkan berita bohong dan menyesatkan yang mengakibatkan kerugian konsumen dalam Transaksi Elektronik sebagaimana dimaksud dalam Pasal 28 ayat (1) dipidana dengan pidana penjara paling lama 6 (enam) tahun dan/atau denda paling banyak Rp1.000.000.000,00 (satu miliar rupiah)."}},{"id":"ID-H049-A2","no":2,"noLabel":{"zh":"第 2 条","en":"Article 2"},"text":{"id":"Setiap Orang yang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan perjudian sebagaimana dimaksud dalam Pasal 27 ayat (2) dipidana dengan pidana penjara paling lama 6 (enam) tahun dan/atau denda paling banyak Rp1.000.000.000,00 (satu miliar rupiah).\n\nSetiap Orang yang dengan sengaja dan tanpa hak menyebarkan informasi yang ditujukan untuk menimbulkan rasa kebencian atau permusuhan individu dan/atau kelompok masyarakat tertentu berdasarkan atas suku, agama, ras, dan antargolongan (SARA) sebagaimana dimaksud dalam Pasal 28 ayat (2) dipidana dengan pidana penjara paling lama 6 (enam) tahun dan/atau denda paling banyak Rp1.000.000.000,00 (satu miliar rupiah).\n**Pasal 45B** Setiap Orang yang dengan sengaja dan tanpa hak mengirimkan Informasi Elektronik dan/atau Dokumen Elektronik yang berisi ancaman kekerasan atau menakut-nakuti yang ditujukan secara pribadi sebagaimana dimaksud dalam Pasal 29 dipidana dengan pidana penjara paling lama 4 (empat) tahun dan/atau denda paling banyak Rp750.000.000,00 (tujuh ratus lima puluh juta rupiah).\n**Pasal II** Undang-Undang ini mulai berlaku pada tanggal diundangkan.\nAgar setiap orang mengetahuinya, memerintahkan pengundangan Undang-Undang ini dengan penempatannya dalam Lembaran Negara Republik Indonesia.\n**Pasal I** Beberapa ketentuan dalam Undang-Undang Nomor 11 Tahun 2008 tentang Informasi dan Transaksi Elektronik (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 58, Tambahan Lembaran Negara Republik Indonesia Nomor 4843) diubah sebagai berikut:1. Di antara angka 6 dan angka 7 **Pasal 1** disisipkan 1 (satu) angka, yakni angka 6a sehingga Pasal 1 berbunyi sebagai berikut:\nPasal 1 Dalam Undang-Undang ini yang dimaksud dengan:"}},{"id":"ID-H049-A3","no":3,"noLabel":{"zh":"第 3 条","en":"Article 3"},"text":{"id":"Setiap Orang yang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan penghinaan dan/atau pencemaran nama baik sebagaimana dimaksud dalam Pasal 27 ayat (3) dipidana dengan pidana penjara paling lama 4 (empat) tahun dan/atau denda paling banyak Rp750.000.000,00 (tujuh ratus lima puluh juta rupiah)."}},{"id":"ID-H049-A4","no":4,"noLabel":{"zh":"第 4 条","en":"Article 4"},"text":{"id":"Setiap Orang yang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan pemerasan dan/atau pengancaman sebagaimana dimaksud dalam Pasal 27 ayat (4) dipidana dengan pidana penjara paling lama 6 (enam) tahun dan/atau denda paling banyak Rp1.000.000.000,00 (satu miliar rupiah)."}},{"id":"ID-H049-A5","no":5,"noLabel":{"zh":"第 5 条","en":"Article 5"},"text":{"id":"Ketentuan sebagaimana dimaksud pada ayat (3) merupakan delik aduan.\n**Pasal 45A**"}}],"pack":"id-p03"};
  FT["ID-H050"] = {"id":"ID-H050","coverage":"full","language":"id","sourceName":"印度尼西亚官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"电子信息与交易法修正案","en":"Law No. 19 of 2016 on the Amendment to Law No. 11 of 2008 on Electronic Information and Transactions","orig":"Undang-Undang Nomor 19 Tahun 2016 tentang Perubahan atas Undang-Undang Nomor 11 Tahun 2008 tentang Informasi dan Transaksi Elektronik","id":"Undang-Undang Nomor 19 Tahun 2016 tentang Perubahan atas Undang-Undang Nomor 11 Tahun 2008 tentang Informasi dan Transaksi Elektronik","vi":"Luật số 19 năm 2016 về Sửa đổi Luật số 11 năm 2008 về Thông tin và Giao dịch Điện tử","th":"พระราชบัญญัติเลขที่ 19 ปี 2016 ว่าด้วยการแก้ไขพระราชบัญญัติเลขที่ 11 ปี 2008 ว่าด้วยข้อมูลและธุรกรรมอิเล็กทรอนิกส์","ms":"Akta No. 19 Tahun 2016 tentang Pindaan Akta No. 11 Tahun 2008 tentang Maklumat dan Transaksi Elektronik"},"level":"law","status":"active","docNumber":"Undang-Undang Nomor 19 Tahun 2016","issuingBody":"印度尼西亚官方发布渠道","promulgatedDate":"2016-11-25","effectiveDate":"2016-11-25","completenessNote":"全文，共 7 条；取自《东盟法律分类》归档中的 TXT 原件，逐字未改写。","country":"ID","countryName":"印度尼西亚","layer":"intl","articles":[{"id":"ID-H050-A1","no":1,"noLabel":{"en":"Article 1","zh":"第 1 条"},"text":{"id":"Setiap Orang yang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan yang melanggar kesusilaan sebagaimana dimaksud dalam Pasal 27 ayat (1) dipidana dengan pidana penjara paling lama 6 (enam) tahun dan/atau denda paling banyak Rp1.000.000.000,00 (satu miliar rupiah)."}},{"id":"ID-H050-A2","no":2,"noLabel":{"en":"Article 2","zh":"第 2 条"},"text":{"id":"Setiap Orang yang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan perjudian sebagaimana dimaksud dalam Pasal 27 ayat (2) dipidana dengan pidana penjara paling lama 6 (enam) tahun dan/atau denda paling banyak Rp1.000.000.000,00 (satu miliar rupiah)."}},{"id":"ID-H050-A3","no":3,"noLabel":{"en":"Article 3","zh":"第 3 条"},"text":{"id":"Setiap Orang yang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan penghinaan dan/atau pencemaran nama baik sebagaimana dimaksud dalam Pasal 27 ayat (3) dipidana dengan pidana penjara paling lama 4 (empat) tahun dan/atau denda paling banyak Rp750.000.000,00 (tujuh ratus lima puluh juta rupiah)."}},{"id":"ID-H050-A4","no":4,"noLabel":{"en":"Article 4","zh":"第 4 条"},"text":{"id":"Setiap Orang yang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan pemerasan dan/atau pengancaman sebagaimana dimaksud dalam Pasal 27 ayat (4) dipidana dengan pidana penjara paling lama 6 (enam) tahun dan/atau denda paling banyak Rp1.000.000.000,00 (satu miliar rupiah)."}},{"id":"ID-H050-A5","no":5,"noLabel":{"en":"Article 5","zh":"第 5 条"},"text":{"id":"Ketentuan sebagaimana dimaksud pada ayat (3) merupakan delik aduan.\n**Pasal 45A**"}}],"pack":"id-p03"};
  FT["ID-H051"] = {"id":"ID-H051","coverage":"full","language":"id","sourceName":"印度尼西亚官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":41,"structureMode":"ARTICLE","title":{"zh":"信托担保法","en":"Law No. 42 of 1999 on Fiduciary Security","orig":"Undang-Undang Nomor 42 Tahun 1999 tentang Jaminan Fidusia","id":"Undang-Undang Nomor 42 Tahun 1999 tentang Jaminan Fidusia","vi":"Luật số 42 năm 1999 về Bảo đảm Tín chấp","th":"พระราชบัญญัติเลขที่ 42 ปี 1999 ว่าด้วยหลักประกันฟิดูเซีย","ms":"Akta No. 42 Tahun 1999 tentang Jaminan Fidusia"},"level":"law","status":"active","issuingBody":"印度尼西亚官方发布渠道","promulgatedDate":"1999","completenessNote":"全文，共 85 条；取自《东盟法律分类》归档中的 MD 原件，逐字未改写。","country":"ID","countryName":"印度尼西亚","layer":"intl","articles":[{"id":"ID-H051-A1","no":1,"noLabel":{"zh":"第 1 条","en":"Article 1"},"text":{"id":"Dalam Undang-undang ini yang dimaksud dengan:\n1. Fidusia adalah pengalihan hak ke pemilikan suatu benda atas dasar kepercayaan dengan ketent uan bahwa benda yang hak kepemilikannya dialihka n tersebut tetap dala m penguasaan pemilik benda.\n2. Jaminan Fidusia adalah hak jami nan atas benda bergerak baik yang berwujud maupun yang tidak berwuj ud dan benda tidak bergerak khususnya bangunan yang tidak da pat dibebani  hak tanggungan sebagaimana dimaksud dalam Undang-undang Nomor 4 Tahun 1996 tentang Hak Tanggungan yang tetap berada dalam penguasaan Pemberi Fidusia, sebagai agunan bagi pelunasan utang tertentu, yang memberikan kedudukan yang diutamak an kepada Penerima Fidusia terhadap kreditor lainnya.\n3. Piutang adalah hak untuk menerima pembayaan.\n4. Benda adalah segala sesuatu yang dapat dimiliki atau dialihkan, baik yang berwujud maupun tidak berwujud, yang terdaftar maupun yang tidak terdaftar, yang bergerak ma upun yang tak bergerak yang tidak dapat dibebani hak tanggungan atau hipotik.\n5. Pemberi Fidusia adalah orang perseorangan atau korporasi pemilik Benda yang menjadi objek Jaminan Fidusia.\n6. Penerima Fidusia adalah ora ng perseorangan atau korporasi yang mempunyai piutang yang pembayar annya dijamin dengan Jaminan Fidusia.\n7. Utang adalah kewajiban yang dinyatakan atau dapat dinyatakan dalam jumlah uang baik dalam ma ta uang Indonesia atau mata uang lainnya, baik secara langsung maupun kontinjen.\n8. Kreditor adalah pihak yang mempunyai piutang karena perjanjian atau undang-undang.\n9. Debitor adalah pihak yang mem punyai utang karena perjanjian atau undang-undang.\n10. Setiap Orang adalah orang perseorangan atau korporasi.\nBAB II\nRUANG LINGKUP\n\nCukup jelas"}},{"id":"ID-H051-A2","no":2,"noLabel":{"zh":"第 2 条","en":"Article 2"},"text":{"id":"Undang-undang ini berlaku terhadap setiap perjanjian yang bertujuan untuk membebani Benda Jaminan Fidusia.\n\nCukup jelas"}},{"id":"ID-H051-A3","no":3,"noLabel":{"zh":"第 3 条","en":"Article 3"},"text":{"id":"Undang-undang ini tidak berlaku terhadap:\na. Hak Tanggungan yang berkaita n dengan tanah dan bangunan, sepanjang peraturan perundang-undangan yang berlaku menentukan jaminan atas benda-benda tersebut wajib didaftar;\nb. Hipotek atas kapal yang terdafta r dengan isi kotor berukuran 20 (dua puluh) M3 atau lebih;\nc. Hipotek atas pesawat terbang; dan\nd. Gadai.\nBAB III\nPEMBEBANAN, PENDAFTARAN, PENGALIHAN DAN\nHAPUSNYA JAMINAN FIDUSIA\nBagian Pertama\nPembebanan Jaminan Fidusia\n\nHuruf a\nBerdasarkan ketentuan in i, maka bangunan di atas ta nah milik orang lain yang tidak dapat dibebani dengan hak ta nggungan berdasarkan Undang-undang Nomor 4 Tahun 1996 tentang Hak Tanggungan, dapat dijadikan objek Jaminaan Fidusia.\nHuruf b Cukup jelas\nHuruf c Cukup jelas\nHuruf d Cukup jelas"}},{"id":"ID-H051-A4","no":4,"noLabel":{"zh":"第 4 条","en":"Article 4"},"text":{"id":"Jaminan Fidusia merupakan perjanjia n ikutan dari suatu perjanian pokok yang menimbulkan kewajiban ba gi para piha k untuk memenuhi suatu prestasi.\n\nYang dimaksud dengan \"prest asi\" dalam ketentuan in i adalah memberikan sesuatu, berbuat sesuatu, atau tidak be rbuat sesuatu, yang dapat dinilai dengan uang."}},{"id":"ID-H051-A5","no":5,"noLabel":{"zh":"第 5 条","en":"Article 5"},"text":{"id":"(1) Pembebanan Benda dengan Jami nan Fidusia dibuat dengan akta notaris dalam bahasa Indonesia dan merupakan akta Jaminan Fidusia.\n(2) Terhadap pembuatan akta Jami nan Fidusia sebagaimana dimaksud dalam ayat (1), dikenakan biaya ya ng besarnya diatur lebih lanjut dengan Peraturan Pemerintah.\n\nAyat (1) Dalam akta Jaminan Fidusia selain  dicantumkan hari dan tanggal, juga dicantumkan mengenai waktu (jam) pembuatan akta tersebut.\nAyat (2) Cukup jelas"}},{"id":"ID-H051-A6","no":6,"noLabel":{"zh":"第 6 条","en":"Article 6"},"text":{"id":"Akta Jaminan Fidusia sebaga imana dimaksud dalam Pasal 5 sekurang-kurangnya memuat:\na. identitas pihak Pemberi dan Penerima Fidusia;\nb. data perjanjian pokok yang dijamin fidusia;\nc. uraian mengenai Benda yang menjadi objek Jaminan Fidusia;\nd. nilai penjaminan; dan e nilai Benda yang menjadi objek Jaminan Fidusia.\n\nHuruf a\nYang dimaksud dengan \"iden titas\" dalam pasal ini adalah meliputi nama lengkap, agama, tempat tinggal, atau tempat kedudukan, tempat dan tanggal lahir, jenis kelamin, status perkawinan, dan pekerjaan.\nHuruf b Yang dimaksud dengan \"data perj anjian pokok\" adalah mengenai macam perjanjian dan utang yang dijamin dengan fidusia.\nHuruf c.\nUraian mengenai Benda yang menjad i objek Jaminan Fidusia cukup dilakukan dengan mengidentifikasikan Benda tersebut, dan dijelaskan mengenai surat bukti kepemilikannya.\nDalam hal benda yang me njadi objek Jaminan Fidusia  merupakan benda dalam persediaan (inventory) yang selalu berubah-ubah dan atau  tidak tetap, seperti stok bahan baku, barang jadi, at au portofolio perusahaan efek, maka dalam akta Jaminan Fidusia dicantumkan uraian menge nai jenis, merek, kualitas dari Benda tersebut.\nHuruf d Cukup jelas\nHuruf c Cukup jelas"}},{"id":"ID-H051-A7","no":7,"noLabel":{"zh":"第 7 条","en":"Article 7"},"text":{"id":"Utang yang pelunasannya dajamin dengan fidusia dapat berupa:\na. utang yang telah ada;\nb. utang yang akan timbul  di kemudian hari yang telah diperjanjikan dalam jumlah tertentu; dan\nc. utang yang pada saat ekse kusi dapat ditentukan jumlahnya berdasarkan perjanjian pokok ya ng menimbulkan kewajiban memenuhi suatu prestasi.\n\nHuruf a\nCukup jelas\nHuruf b Utang yang akan timbul di kemudian hari yang dikena l dengan istilah \"kontinjen\", misalnya utang yang timbul dari pembayaran yang dilakukan oleh kreditor untuk kepentingan debitor dalam rangka pelaksanaan garansi bank.\nHuruf c Utang yang dimaksud dala m ketentuan ini adalah ut ang bunga atas pinjaman pokok dan biaya lainnya yang jumlahnya dapat ditentukan kemudian."}},{"id":"ID-H051-A8","no":8,"noLabel":{"zh":"第 8 条","en":"Article 8"},"text":{"id":"Jaminan Fidusia dapat diberikan ke pada lebih dari satu Penerima Fidusia atau kepada kuasa atau wakil dari Penerima Fidusia tersebut.\n\nKetentuan ini dimaksudkan sebagai pember ian fidusia kepada lebih dari satu Penerima Fidusia dalam rangka pembiayaan kredit konsorsium.\nYang dimaksud dengan \"kuasa \" adalah orang yang menda pat kuasa khusus dari Penerima Fidusia untuk mewakili kepen tingannya dalam penerimaan Jaminan Fidusia dari Pemberi Fidusia.\nYang dimaksud dengan \"wakil\" adalah  orang yang seca ra hukum dianggap mewakili Penerima Fidusia dalam peneri maan Jaminan Fidusia, misalnya, Wali Amanat dalam mewakili kepentingan pemegang obligasi."}},{"id":"ID-H051-A9","no":9,"noLabel":{"zh":"第 9 条","en":"Article 9"},"text":{"id":"(1) Jaminan Fidusia dapat diberikan terhadap satu atau lebih satuan atau jenis Benda, termasuk piutang, ba ik yang telah ada pada saat jaminan diberikan maupun yang diperoleh kemudian.\n(2) Pembebanan jaminan atas Be nda atau piutang yang diperoleh kemudian sebagaimana dimaksud dalam ayat (1) tidak perlu dilakukan dengan perjanjian jaminan tersendiri.\n\nKetentuan dalam pasal ini penting dipandang dari segi  komersial. Ketentuan ini secara tegas membolehkan Jaminan Fidusia mencakup Benda yang diperoleh di kemudian hari. Hal ini menunjukkan Undang-undang ini dijamin fleksibilitas yang berkenaan dengan ihwal Benda yang dapa t dibebani Jamina n Fidusia bagi pelunasan utang."}},{"id":"ID-H051-A10","no":10,"noLabel":{"zh":"第 10 条","en":"Article 10"},"text":{"id":"Kecuali diperjanjikan lain:\na. Jaminan Fidusia meliputi has il dari Benda yang menjadi objek Jaminan Fidusia.\nb. Jaminan Fidusia meliputi klaim asuransi, dalam hal Benda yang menjadi objek Jaminan Fidusia diasuransikan.\nBagian Kedua\nPendaftaran Jaminan Fidusia\n\nHuruf a\nYang dimaksud dengan \"has il dari Benda yang menjadi objek Jaminana Fidusia\" adalah segala sesuatu yang diperoleh dari Benda yang dibebani Jaminan Fidusia.\nHuruf b Ketentuan dalam huruf b ini dimaksudkan untuk menega skan apabila Benda itu diasuransikan, maka klaim asuransi tersebut merupakan hak Penerima Fidusia."}},{"id":"ID-H051-A11","no":11,"noLabel":{"zh":"第 11 条","en":"Article 11"},"text":{"id":"(1) Benda yang dibebani dengan Jaminan Fidusia wajib didaftarkan.\n(2) Dalam hal Benda yang dibebani dengan Jamina n Fidusia berada di luar wilayah negara Republik I ndonesia, kewajiban sebagaimana dimaksud dalam ayat (1) tetap berlaku.\n\nPendaftaran Benda yang dibe bani dengan Jaminan Fidusia  dilaksanakan ditempat kedudukan Pemberi Fidusia, dan pendaft arannya mencakup benda, baik yang berada di dalam maupun di luar w ilayah negara Republik Indonesia untuk memenuhi asas publisitas, sekaligus me rupakan jaminan kepastian terhadap kreditor lainnya mengenai Benda yang telah dibebani Jaminan Fidusia."}},{"id":"ID-H051-A12","no":12,"noLabel":{"zh":"第 12 条","en":"Article 12"},"text":{"id":"(1) Pendaftaran Jaminan Fidusia sebagaimana dimaksud dalam Pasal 11\nayat (1) dilakukan pada Kantor Pendaftaran Fidusia.\n(2) Untuk pertama kali, Kantor Pendaftaran Fidusia didirikan di Jakarta dengan wilayah kerja mencakup se luruh wilayah negara Republik Indonesia.\n(3) Kantor Pendaftaran Fidusia se bagaimana dimaksud dalam ayat (2) berada dalam lingkup tugas Departemen Kehakiman.\n(4) Ketentuan mengenai pembentuka n Kantor Pendaftaran Fidusia untuk daerah lain dan penetapan wilayah kerjanya  diatur dengan Keputusan Presiden.\n\nKantor Pendaftaran Fidusia merupaka n bagian dalam lingkungan Departemen Kehakiman dan bukan instansi yang mandiri atau unit pelaksana teknis.\nKantor Pendaftaran Fidusia didirikan untuk pertama ka li di Jakarta dan secara bertahap, sesuai dengan keperluan, di i bukota propinsi di selu ruh wilayah negara Republik Indoensia.\nDalam hal Kantor Pendaftaran Fidusia be lum didirikan di tiap Daerah Tingkat II maka wilayah kerja Kantor Pendaftaran Fidusia di ibukot a propinsi meliputi seluruh daerah Tingkat II yang berada di lingkungan wilayahnya.\nPendirian Kantor Pendaftaran Fidusia di daerah Tingkat II, dapat disesuaikan dengan Undang-undang Nomor 22 Tahun 1999 tentang Pemerintahan Daerah."}},{"id":"ID-H051-A13","no":13,"noLabel":{"zh":"第 13 条","en":"Article 13"},"text":{"id":"(1) Permohonan pendaftaran Jaminan Fidusia dilakukan oleh Penerima Jaminan Fidusia dilakukan oleh Pe nerimaan Fidusia, kuasa atau wakilnya dengan melampirkan pe rnyataan pendaftaran Jaminan Fidusia.\n(2) Pernyataan pendaftaran sebagaimana dimaksud dalam ayat (1) memuat:\na. indentitas pihak Pemberi dan Penerima Fidusia;\nb. tanggal, nomor akta Jamina na Fidusia, nama, dan tempat kedudukan notaris yang membuat akta Jaminan Fidusia;\nc. data perjanjian pokok yang dijamin Fidusia;\nd. uraian mengenai Benda yang menjadi objek Jaminan Fidusia;\ne. nilai penjaminan; dan\nf. nilai Benda yang menjadi objek Jaminan Fidusia.\n(3) Kantor Pendaftaran Fidusia me muat Jaminan Fidusia dalam Buku Daftar Fidusia pada tanggal yang sama dengan tanggal penerimaan permohonan pendaftaran.\n(4) Ketentuan lebih lanj ut mengenai tata cara pendaftaran Jaminan Fidusia dan biaya pendaftaran diatur dengan Peraturan Pemerintah.\n\nAyat (1) Cukup jelas\nAyat (2) Cukup jelas\nAyat (3) Ketentuan ini dimaksudkan agar Kant or Pendaftaran Fidusia tidak melakukan penilaian terhadap kebenaran yang dica ntumkan dalam pernya taan Pendaftaran jaminan Fidusia, akan tetapi hanya melakukan pengecekan data sebagaimana dimaksud dalam Pasal 13 ayat (2).\nAyat (4) Cukup jelas"}},{"id":"ID-H051-A14","no":14,"noLabel":{"zh":"第 14 条","en":"Article 14"},"heading":{"id":"ayat (1) dicantumkan kata-kata \"DEMI KEADILAN"},"text":{"id":"(1) Kantor Pendaftaran Fidusia me nerbitkan dan menyerahkan kepada Penerima Fidusia Sertifikat Ja minana Fidusia pada tanggal yang sama dengan tanggal penerimaan permohonan pendaftaran.\n(2) Sertifikat Jaminan Fidusia yang merupakan salinan dari Buku Daftar Fidusia memuat catatan tenta ng hal-hal sebagaimana dimaksud dalam Pasal 13 ayat (2).\n(3) Jaminan Fidusia lahir pada  tanggal yang sama dengan tanggal dicatatnya Jaminana Fidusia dalam Buku Daftar Fidusia.\n\nBERDASARKAN KETUHANAN YANG MAHA ESA\".\n(2) Sertifikat Jaminan Fidusia se bagaimana dimaksud dalam ayat (1) mempunyai kekuatan eksekutoria l yang sama dengan putusan pengadilan yang telah memperoleh kekuatan hukum tetap.\n(3) Apabila debitor cidera janji, Penerima Fidusia mempunyai hak untuk menjual Benda yang menjadi obj ek Jaminan Fidusia atas kekuasaannya sendiri.\n\nAyat (1) Cukup jelas\nAyat (2) Cukup jelas\nAyat (3) Ketentuan ini tidak mengurangi berlakunya Pasal 613 Kitab Undang-undang Hukum Perdata bagi pengalihan piutang atas nama dan kebendaan tak berwujud lainnya."}},{"id":"ID-H051-A15","no":15,"noLabel":{"zh":"第 15 条","en":"Article 15"},"text":{"id":"(1) Dalam Sertifikat Jaminana Fi dusia sebagaimana dimaksud dalam\n\nayat (2) oleh Penerima Fidusia.\nb. penjualan Benda yang menjadi objek Jaminan Fidusia atas kekuasaan Penerima Fidusia sendiri melalui pelelangan umum serta mengambil pelunasan piutangnya dari hasil penjualan;\nc. penjualan di bawah ta ngan yang dilakukan berdasarkan kesepakatan Pemberi dan Peneri ma Fidusia jika dengan cara demikian dapat diperoleh ha rga tertinggi yang menguntungkan para pihak.\n(2) Pelaksanaan penjualan sebagaimana dimaksud dalama ayat (1) huruf c dilakukan setelah lewa t waktu 1 (satu) bulan sejak diberitahukan secara tertulis oleh Pemberi dan atau Penerima Fidusia kepada pihak-pihak yang berkep entingan dan diumumka n sedikitnya dalam 2 (dua) surat kabar yang tersebar di daerah yang bersangkutan.\n\nAyat (1) Cukup jelas\nAyat (2) Dalam ketentuan ini, yang dimaksud dengan \"kekuatan eksekutorial\" adalah langsung dapat dilaksanakan tanpa melalui pengadilan dan bersifat final serta mengikat para pihak untuk melaksanakan putusan tersebut.\nAyat (3) Salah satu ciri Jaminan Fidusia adalah  kemudahan dalam pelaksanaan eksekusinya yaitu apabila pihak Pemberi Fidusia ci dera janji. Oleh karena itu dalam Undang-undang ini dipandang perlu diat ur secara khusus tentang eksekusi Jaminan Fidusia melalui lembaga parate eksekusi."}},{"id":"ID-H051-A16","no":16,"noLabel":{"zh":"第 16 条","en":"Article 16"},"text":{"id":"(1) Apabila terjadi perubahan menge nai hal-hal yang tercantum dalam Sertifikat Jaminan Fidusia seba gaimana dimaksud dalam Pasal 14\nayat (2), Penerima Fidusia wajib mengajukan permohonan pendaftaran atas perubahan terse but kepada Kantor Pendaftaran Fidusia.\n(2) Kantor Pendaftaran Fidusia pa da tanggal yang sama dengan tanggal penerimaan permohonan peruba han, melakukan pencatatan perubahan tersebut dalam Buku Da ftar Fidusia dan menerbitkan Pernyataan Perubahan yang merupakan bagian tak terpisahkan dari Sertifikat Jaminan Fidusia.\n\nAyat (1) Perubahan mengenai hal-hal yang tercan tum dalam Sertifikat Jaminaan Fidusia, harus diberitahukan kepada para pihak. Perubahan ini tidak perlu dilakukan dengan akta notaris dalam rangka efisiensi untuk meme nuhi kebutuhan dunia usaha.\nAyat (2) Cukup jelas"}},{"id":"ID-H051-A17","no":17,"noLabel":{"zh":"第 17 条","en":"Article 17"},"text":{"id":"Pemberi Fidusia dilarang melakukan fidusia ulang terhadap Benda yang menjadi objek Jaminan Fidusia yang sudah terdaftar.\n\nFidusia ulang oleh Pemberi Fidusia, baik  debitor maupun penjamin pihak ketiga, tidak memungkinkan atas Benda yang menjad i objek Jaminan Fi dusia karena hak kepemilikan atas Benda tersebut telah beralih kepada Penerima Fidusia."}},{"id":"ID-H051-A18","no":18,"noLabel":{"zh":"第 18 条","en":"Article 18"},"text":{"id":"Segala keterangan mengenai Benda  yang menjadi objek Jaminan Fidusia yang ada pada Kantor Pendaftaran Fidusia terbuka untuk umum.\nBagian Ketiga\nPengalihan Jaminan Fidusia\n\nCukup jelas"}},{"id":"ID-H051-A19","no":19,"noLabel":{"zh":"第 19 条","en":"Article 19"},"text":{"id":"(1) Pengalihan hak atas piuta ng yang dijaminan dengan fidusia mengakibatkan beralihnya demi hukum segala hak dan kewajiban Penerima Fidusia kepada kreditor baru.\n(2) Beralihnya Jaminan Fidusia sebagaimana dimaksud dalam ayat (1) didaftarkan oleh kreditor baru kepada Kantor Pendaftaran Fidusia.\n\n\"Pengalihan hak atas piutang\" dalam ketentuan ini, dikenal de ngan istilah \"cessie\" yakni pengalihan piutang ya ng dilakukan dengan akta oten tik atau akta di bawah tangan. Dengan adanya cessie ini, maka  segala hak dan ke wajiban Penerima Fidusia lama beralih kepada Penerima Fidusia baru dan pengalihan hak atas piutang tersebut diberitahukan kepada Pemberi Fidusia."}},{"id":"ID-H051-A20","no":20,"noLabel":{"zh":"第 20 条","en":"Article 20"},"text":{"id":"Jaminan Fidusia tetap mengikuti Be nda yang menjadi objek Jaminan Fidusia dalam tangan siapapun Benda tersebut berada, kecuali pengalihan atas benda persediaan yang menjadi objek Jaminan Fidusia.\n\nKetentuan ini mencakup prinsip \"droit de suite\" yang telah mer upakan bagian dari peraturan perundang-undangan Indonesia dalam kaitannya dengan hak mutlak atas kebendaan (in rem)."}},{"id":"ID-H051-A21","no":21,"noLabel":{"zh":"第 21 条","en":"Article 21"},"heading":{"id":", apabila Penerima Fidusia  setuju bahwa Pemberi Fidusia"},"text":{"id":"(1) Pemberi Fidusia dapat mengalihka n benda persediaan yang menjadi objek Jaminan Fidusia dengan cara dan prosedur yang lazim dilakukan dalam usaha perdagangan.\n(2) Ketentuan sebagaimana dimaksud dalam ayat (1) tidak berlaku, apabila telah terjadi cidera jan ji oleh debitor dan atas Pemberi Fidusia pihak ketiga.\n(3) Benda yang menjadi objek Jami nan Fidusia yang telah dialihkan sebagaimana dimaksud dalam ayat (1) wajib diganti oleh Pemberi Fidusia dengan objek yang setara.\n(4) Dalam hal Pemberi Fidusia cidera  janji, maka hasil pengalihan dan atau tagihan yang timbul karena pengalihan sebagaimana dimaksud dalam ayat (1), demi hukum menjadi objek Jaminan Fidusia pengganti dari objek Jaminan Fidusia yang dialihkan.\n\ndapat menggunakan, menggabungka n, mencampur, atau mengalihkan Benda atau hasil da ri Benda yang menjadi objek Jaminan Fidusia, atau menyetu jui melakukan penagihan atau melakukan kompromi atas piutang, maka perset ujuan tersebut tidak berarti bahwa Penerima Fidusia melepaskan Jaminan Fidusia.\n(2) Pemberi Fidusia dilarang me ngalihkan, menggadaikan, atau menyewakan kepada pihak lain Be nda yang menjadi objek Jaminan Fidusia yang tidak merupakan be nda persediaan, kecuali dengan persetujuan tertulis terlebih dahulu dari Penerima Fidusia.\n\nKetentuan ini menegaskan kembali ba hwa Pemberi Fidusia  dapat mengalihkan benda persediaan yang menjadi objek Jaminan Fidusia. Namun demikian untuk menjaga kepentingan Penerima Fidusia, maka Benda yang di alihkan tersebut wajib diganti dengan objek yang setara.\nYang dimaksud dengan\"mengalihkan\" anta ra lain termasuk menjual atau menyewakan dalam rangka kegiatan usahanya.\nYang dimaksud dengan\"setara\" tidak hanya nilainya tetapi juga jenisnya.\nYang dimaksud dengan \"cidera janji\" adal ah tidak memenuhi prestasi, baik yang berdasarkan perjanjian pokok, perjanjia n Jaminan Fidusia maupun perjanjian jaminan lainnya."}},{"id":"ID-H051-A22","no":22,"noLabel":{"zh":"第 22 条","en":"Article 22"},"text":{"id":"Pembeli benda yang menjadi objek Jaminan Fidusia yang merupakan benda persediaan bebas dari tunt utan meskipun pembeli tersebut mengetahui adanya Jaminan Fidus ia itu, dengan ketentuan bahwa pembeli telah membayar lunas harga penjualan Benda tersebut sesuai dengan harga pasar.\n\nYang dimaksud dengan \"harga pasar\" adal ah harga yang waja r yang berlaku di pasar pada saat penjualan Benda tersebut, sehingga tidak mengesankan adanya penipuan dari pihak Pemberi Fidusia dalam melakukan penjualan Benda tersebut."}},{"id":"ID-H051-A23","no":23,"noLabel":{"zh":"第 23 条","en":"Article 23"},"text":{"id":"(1) Dengan tidak mengurangi ketent uan sebagaimana dimaksud dalam\n\nAyat (1) Yang dimaksud dengan \"m enggabungkan\" adalah penyatu an bagian-bagian dari Benda tersebut.\nYang dimaksud dengan \"mencampur\" ad alah penyatuan Benda yang sepadan dengan Benda yang menjadi objek Jaminan Fidusia.\nAyat (2) Yang dimaksud dengan \"be nda yang tidak merupakan benda persediaan\" misalnya mesin produksi, mobil pribadi, atau ru mah pribadi yang menjadi objek Jaminan Fidusia."}},{"id":"ID-H051-A24","no":24,"noLabel":{"zh":"第 24 条","en":"Article 24"},"text":{"id":"Penerima Fidusia tidak menanggung ke wajiban atas akibat tindakan atau kelalaian Pemberi Fidusia  baik yang timbul dari hubungan kontraktual atau yang timbul da ri perbuatan melanggar hukum sehubungan dengan penggunaan dan pengalihan Benda yang menjadi objek Jaminan Fidusia.\nBagian Keempat\nHapusnya Jaminan Fidusia\n\nCukup jelas"}},{"id":"ID-H051-A25","no":25,"noLabel":{"zh":"第 25 条","en":"Article 25"},"text":{"id":"(1) Jaminan Fidusia hapus karena hal-hal sebagai berikut:\na. hapusnya utang yang dijamin dengan fidusia;\nb. pelepasan hak atas Jaminan Fi dusia oleh Penerima Fidusia; atau\nc. musnahnya Benda yang me njadi objek Jaminan Fidusia.\n(2) Musnahnya Benda yang menjad i objek Jaminan Fidusia tidak menghapuskan klaim asuransi seba gaimana dimaksud dalam Pasal 10 huruf b.\n(3) Penerima Fidusia memberitahuka n kepada Kantor Pendaftaran Fidusia mengenai hapusnya Jaminan Fidusia sebagaimana dimaksud dalam ayat (1) dengan melampirka n pernyataan mengenai hapusnya utang, pelepasan hak, atau mu snahnya Benda yang menjadi objek Jaminan Fidusia tersebut.\n\nAyat (1) Sesuai dengan ikutan dari Jaminan Fidusia, maka adanya  Jaminan Fidusia tergantung pada adanya piutang yang dijamin pel unasannya. Apabila piutang tersebut hapus karena ha pusnya utang atau karena pelepasan, maka dengan sendirinya Jaminan Fidusia yang bersangkutan menjadi hapus.\nYang dimaksud dengan \"hapus nya utang\" antara lain karena pelunasan dan bukti hapusnya utang berupa keterangan yang dibuat kreditor.\nAyat (2) Dalam hal Benda yang menj adi objek Jaminan Fidusia musnah dan Benda tersebut diasuransikan maka klaim asuransi akan menjadi pengganti objek Jaminan Fidusia tersebut.\nAyat (3) Cukup jelas"}},{"id":"ID-H051-A26","no":26,"noLabel":{"zh":"第 26 条","en":"Article 26"},"text":{"id":"(1) Dengan hapusnya Jaminan Fidusia sebagaimana dimaksud dalam\npasal 25, Kantor Pendaftaran Fidus ia mencoret pencatatan Jaminan Fidusia dari Buku Daftar Fidusia.\n(2) Kantor Pendaftaran Fidusia menerbitkan surat keterangan yang menyatakan Sertifikat keteranga n yang menyatakan Sertifikat Jaminan Fidusia yang bersangkutan tidak berlaku lagi.\nBAB IV\nHAK MENDAHULU\n\nCukup jelas"}},{"id":"ID-H051-A27","no":27,"noLabel":{"zh":"第 27 条","en":"Article 27"},"text":{"id":"(1) Penerima Fidusia memiliki hak yang didahulukan terhadap kreditor lainnya.\n(2) Hak yang didahulukan sebagaimana dimaksud dalam ayat (1) adalah hak Penerima Fidusia untuk menga mbil pelunasan piutangnya atas hasil eksekusi Benda yang menjadi objek Jaminan Fidusia.\n(3) Hak yang didahulukan dari Penerima Fidusia tidak hapus karena adanya kepailitan dan atau likuidasi Pemberi Fidusia.\n\nAyat (1) Hak yang didahulukan di hitung sejak tanggal pendaft aran Benda yang menjadi objek Jaminan Fidusia pada Kantor Pendaftaran Fidusia.\nAyat (2) Cukup jelas\nAyat (3) Ketentuan dalam ayat ini berhubungan dengan ketentuan bahw a Jaminan Fidusia merupakan hak agunan atas kebendaan bagi pelunasan utang. Di samping itu, ketentuan dalam Undang-undang tenta ng Kepailitan menentukan bahwa Benda yang menjadi objek Jaminan Fidusia berada di luar kepailitan dan atau likuidasi."}},{"id":"ID-H051-A28","no":28,"noLabel":{"zh":"第 28 条","en":"Article 28"},"text":{"id":"Apabila atas Benda yang sama menjadi objek Jaminan Fidusia lebih dari 1 (satu) perjanjian Jaminan Fi dusia, maka hak yang didahulukan sebagaimana dimaksud dalam Pasal 27, diberikan ke pada pihak yang lebih dahulu mendaftarkannya pada Kantor Pendaftaran Fidusia.\nBAB V\nEKSEKUSI JAMINAN FIDUSIA\n\nCukup jelas"}},{"id":"ID-H051-A29","no":29,"noLabel":{"zh":"第 29 条","en":"Article 29"},"text":{"id":"(1) Apabila debitor atau Pemberi Fidusia cidera janji, eksekusi terhadap Benda yang menjadi objek Jamina n Fidusia dapat dilakukan dengan cara:\na. pelaksanaan titel eksekutor ial sebagaimana dimaksud dalam\n\nCukup jelas"}},{"id":"ID-H051-A30","no":30,"noLabel":{"zh":"第 30 条","en":"Article 30"},"text":{"id":"Pemberi Fidusia wajib menyera hkan Benda yang menjadi objek Jaminan Fidusia dalam rangka pelaksanaan eksekusi Jaminan Fidusia.\n\nDalam hal Pemberi Fidusia tidak me nyerahkan Benda yang menjadi objek Jaminan Fidusia pada wakt u eksekusi dilaksanakan, Pe nerima Fidusia berhak mengambil Benda yang menjadi objek Jami nan Fidusia dan ap abila perlu dapat meminta bantuan pihak yang berwenang."}},{"id":"ID-H051-A31","no":31,"noLabel":{"zh":"第 31 条","en":"Article 31"},"text":{"id":"Dalam hal Benda yang menjadi objek Jaminan Fidusia terdiri atas benda perdagangan atau efek yang dapat dijual di pasar atau di bursa, penjualannya dapat dilakukan di tempat-tempat tersebut sesuai dengan peraturan perundang-undangan yang berlaku.\n\nCukup jelas"}},{"id":"ID-H051-A32","no":32,"noLabel":{"zh":"第 32 条","en":"Article 32"},"text":{"id":"Setiap janji untuk melaksanakan eksekusi terhadap Benda yang menjadi objek Jaminan Fidusia dengan cara yang bertentangan dengan ketentuan sebagaimana dimaksud dalam pasal 29 dan Pasal 31, batal demi hukum.\n\nCukup jelas"}},{"id":"ID-H051-A33","no":33,"noLabel":{"zh":"第 33 条","en":"Article 33"},"text":{"id":"Setiap janji yang memberi kewenanga n kepada Pember i Fidusia untuk memiliki Benda yang menjadi objek Jaminan Fidusia apabila debitor cidera janji, batal demi hukum.\n\nCukup jelas"}},{"id":"ID-H051-A34","no":34,"noLabel":{"zh":"第 34 条","en":"Article 34"},"text":{"id":"(1) Dalam hal hasil eksekusi melebi hi nilai penjaminan, Penerima Fidusia wajib mengembalikan kele bihan tersebut kepada Pemberi Fidusia.\n(2) Apabila hasil eksekusi tidak mencukupi untuk pel unasan utang, debitor tetap bertanggung jawab atas utang yang belum terbayar.\nBAB VI\nKETENTUAN PIDANA\n\nCukup jelas"}},{"id":"ID-H051-A35","no":35,"noLabel":{"zh":"第 35 条","en":"Article 35"},"text":{"id":"Setiap orang yang de ngan sengaja memalsukan, mengubah, menghilangkan atau dengan cara apapun memberikan keterangan secara menyesatkan, yang jika hal tersebut diketahui oleh salah satu pihak tidak melahirkan perjanjian Jamina n Fidusia, dipidana  dengan pidana penjara paling singkat 1 (satu) tahun dan paling lama 5 (lima) tahun dan denda paling sedikit Rp.10.000.000,-(s epuluh juta rupiah) dan paling banyak Rp.100.000.000,- (seratus juta rupiah).\n\nCukup jelas"}},{"id":"ID-H051-A36","no":36,"noLabel":{"zh":"第 36 条","en":"Article 36"},"text":{"id":"Pemberi Fidusia yang mengalihkan,  menggadaikan, atau menyewakan Benda yang menjadi objek Jamina n Fidusia sebagaimana dimaksud dalam Pasal 23 ayat (2) yang dila kukan tanpa persetujuan tertulis terlebih dahulu dari Penerima Fidus ia, dipidana denga n pidana penjara paling lama 2 (dua) tahun dan de nda paling banyak Rp.50.000.000,- (lima puluh juta rupiah).\nBAB VII\nKETENTUAN PERALIHAN\n\nCukup jelas"}},{"id":"ID-H051-A37","no":37,"noLabel":{"zh":"第 37 条","en":"Article 37"},"text":{"id":"(1) Pembebanan Benda yang menjadi objek Jaminan Fi dusia yang telah ada sebelum berlakunya Undang-undang ini, tetap berlaku sepanjang tidak bertentangan dengan Undang-undang ini.\n(2) Dalam jangka waktu selambat-l ambatnya 60 (enam puluh) hari terhitung sejak berdirinya Kant or Pendaftaran Fidusia, semua perjanjian Jaminan Fidusia harus sesuai dengan ketentuan dalam Undang-undang ini, kecuali ke tentuan mengenai kewajiban pembuatan akta Jaminan Fidusia sebagaimana dimaksud dalam pasal 5 ayat (1).\n(3) Jika dalam jangka waktu seba gaimana dimaksud dalam ayat (2) tidak dilakukan penyesuaian, maka  perjanjian Jaminan Fidusia tersebut bukan merupaka n hak agunan atas kebendaan sebagaimana dimaksud dalam Undang-undang ini.\n\nAyat (1) Cukup jelas\nAyat (2) Cukup jelas\nAyat(3)\nBerdasarkan ketentuan ayat ini, ma ka perjanijan Jaminan Fidusia yang tidak didaftar tidak mempunyai hak yang didahul ukan (preferen) baik di dalam maupun di luar kepailitan dan atau likuidasi."}},{"id":"ID-H051-A38","no":38,"noLabel":{"zh":"第 38 条","en":"Article 38"},"text":{"id":"Sepanjang tidak bertentangan de ngan ketentuan da lam Undang-undang ini, semua peraturan perundang- undangan mengenai fidusia tetap berlaku sampai dengan dicabut, diganti, atau diperbaharui.\nBAB VIII\nKETENTUAN PENUTUP\n\nCukup jelas"}},{"id":"ID-H051-A39","no":39,"noLabel":{"zh":"第 39 条","en":"Article 39"},"text":{"id":"Kantor Pendaftaran Fidusia sebagaimana dimaksud dalam Pasal 12 ayat\n(2) dibentuk dalam jangka waktu pali ng lambat 1 (satu) tahun setelah Undang-undang ini diundangkan.\n\nCukup jelas"}},{"id":"ID-H051-A40","no":40,"noLabel":{"zh":"第 40 条","en":"Article 40"},"text":{"id":"Undang-undang ini disebut Undang-undang Fidusia.\n\nCukup jelas"}},{"id":"ID-H051-A41","no":41,"noLabel":{"zh":"第 41 条","en":"Article 41"},"text":{"id":"Undang-undang ini mulai berlaku pada tanggal diundangkan.\nAgar setiap orang mengetahui nya, memerintahkan pengundangan Undang-undang ini dengan penempata nnya dalam Lembaran Negara Republik Indonesia.\nDisahkan di Jakarta pada tanggal 30 September 1999 PRESIDEN REPUBLIK INDONESIA, t t d .\nBACHARUDDIN JUSUF HABIBIE\nDiundangkan di Jakarta pada tanggal 30 September 1999 MENTERI NEGARA SEKRETARIS NEGARA REPUBLIK INDONESIA, ttd.\nMULADI\nLEMBARAN NEGARA REPUBLIK INDOENSIA TAHUN 1999 NOMOR 168.\nPENJELASAN\nATAS\nUNDANG-UNDANG REPUBLIK INDONESIA\nNOMOR 42 TAHUN 1999 TENTANG JAMINAN FIDUSIA\nI. UMUM\n1. Pembangunan ekonomi, sebagai bagian dari pembangunan na sional, merupakan salah satu upaya untuk mencapai masyar akat yang adil dan makmur berdasarkan Pancasila dan Undang-Undang Dasar 1945. Dalam rangka memelihara dan meneruskan pembangunan yang berkes inambungan, para pelaku pembangunan baik pemerintah maupun masyarakat, baik perseoranga n maupun badan hukum, memerlukan dana yang besar. Seiri ng dengan meningkat nya kegiatan pembangunan, meningkat pul a kebutuhan terhadap pendanaan, yang sebagian besar dana yang diperlukan untuk memenuhi kebutuhan tersebut diperoleh melalui kegiatan pinjam meminjam.\n2. Selama ini, kegiatan pijam-me minjam dengan menggunakan hak tanggungan atau hak jaminan telah diatur dalam Undang-undang Nomor 4 Tahun 1996 tentang Hak Tanggungan yang merupakan pelaksanaan dari Pasal 51 Undang-undang Nomor 5 Tahun 1960 tentang Undang- undang Pokok Agraria, da n sekaligus sebagai pengganti dari lembaga Hipotek atas tana h dan credietverband. Di samping itu, hak jaminan lainnya yang banyak digunakan pada dewasa ini  adalah Gadai, Hipotek selain tanah, dan Jamina n Fidusia. Undang-unda ng yang berkaitan dengan Jaminan Fidusia adalah Pa sal 15 Undang-undang Nomor 4 Tahun 1992 tentang Perumahan dan Permukiman, yang menentukan bahwa rumah-rumah yang dibangun di atas tana h yang dimiliki oleh pihak la in dapat dibebani dengan Jaminan Fidusia. Selain itu, U ndang-undang Nomor 16 Tahun 1985 tentang Rumah Susun mengatur mengenai hak milik atas satuan rumah susun yang dapat dijadikan jaminan utang de ngan dibebani fidusia, jika tanahnya tanah hak pakai atas tanah negara.\nJaminan Fidusia telah digunakan di Indonesia sejak zaman penjajahan Belanda sebagai suatu bentuk jaminan yang lahir dari yurisprudensi. bentuk jaminan ini digunakan secara luas dalam transaks i pinjam-meminjam karena proses pembebanannya dianggap sede rhana, mudah, dan cepat,  tetapi tidak menjamin adanya kepastian hukum.\nLembaga Jaminan Fidusia memungkinka n kepada para Pe mberi Fidusia untuk menguasai Benda yang dijaminkan, unt uk melakukan kegiatan usaha yang dibiayai dari pinjaman dengan mengguna kan Jaminan Fidusia. Pada awalnya, Benda yang menjadi objek fidusia terbatas  pada kekayaan be nda bergerak yang berwujud dalam bentuk perala tan. Akan tetapi dalam perkembangan selanjutnya, Benda yang menjadi objek fidusia termas uk juga kekayaan be nda bergerak yang tak berwujud, maupun benda tak bergerak.\n3. Undang-undang ini, dimaksudkan untuk menampung kebutuhan masyarakat mengenai pengaturan Jaminan Fidusia sebagai salah satu sarana untuk membantu kegiatan usaha dan untuk memberikan ke pastian hukum kepada  para pihak yang berkepentingan.\nSeperti telah dijelaskan bahwa Jaminan Fidusia memberikan kemudahan bagi para pihak yang menggunakannya, khususnya bagi Pemberi Fidusia. Namun sebaliknya karena Jaminan Fidusia tid ak didaftarkan, kurang me njamin kepentingan pihak yang menerima fidusia. Pemberi Fidusia  mungkin saja menjaminkan benda yang telah dibebani dengan fidus ia kepada pihak lain ta npa sepengetahuan Penerima Fidusia.\nSebelum Undang-undang ini dibentuk, pada umumnya Benda yang menjadi objek Jaminan Fidusia adalah benda  bergerak yang terdiri dari benda dalam persediaan (inventory), benda dagangan, piutang, peralatan mesin,  dan kendaraan bermotor.\nOleh karena itu, guna memenuhi kebutuha n masyarakat yang terus berkembang, maka menurut Undang-undang ini objek Ja minan Fidusia dibe rikan pengertian yang luas yaitu benda bergerak  yang berwujud maupun ta k berwujud, dan benda tak bergerak yang tidak da pat dibebani de ngan hak tanggungan sebagaimana dimaksud ditentukan dalam Undang-undang Nomor 4 Tahun 1996 tentang Hak Tanggungan.\nDalam Undang-undang ini, diatur tentang pendaftar an Jaminan Fidusia guna memberikan kepastian hukum kepada para pihak yang berkepentingan dan pendaftaran Jaminan Fidusia memberikan hak yang didahulukan (preferen) kepada Penerima Fidusia terhadap kreditor lain. Karena Jaminan Fidusia memberikan hak kepada pihak Pemberi Fidusia untuk menguasai Be nda yang menjadi objek Jaminan Fidusia berdasarkan kepercayaan , maka diharapkan sistem pendaftaran yang diatur dalam Undang- undang ini dapat memberikan  jaminan kepada pihak Penerima Fidusia dan pi hak yang mempunyai kepen tingan terhadap Benda tersebut.\nII. PASAL DEMI PASAL\n\nCukup jelas TAMBAHAN LEMBARAN NEGARA REPUBLIK INDONESIA NOMOR 3889"}}],"pack":"id-p03"};
  FT["ID-H052"] = {"id":"ID-H052","coverage":"full","language":"id","sourceName":"印度尼西亚官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"电子信息与交易法第二次修正案","en":"Law No. 1 of 2024 on the Second Amendment to Law No. 11 of 2008 on Electronic Information and Transactions","orig":"Undang-Undang Nomor 1 Tahun 2024 tentang Perubahan Kedua atas Undang-Undang Nomor 11 Tahun 2008 tentang Informasi dan Transaksi Elektronik","id":"Undang-Undang Nomor 1 Tahun 2024 tentang Perubahan Kedua atas Undang-Undang Nomor 11 Tahun 2008 tentang Informasi dan Transaksi Elektronik","vi":"Luật số 1 năm 2024 về Sửa đổi Lần thứ hai Luật số 11 năm 2008 về Thông tin và Giao dịch Điện tử","th":"พระราชบัญญัติเลขที่ 1 ปี 2024 ว่าด้วยการแก้ไขครั้งที่สองแห่งพระราชบัญญัติเลขที่ 11 ปี 2008 ว่าด้วยข้อมูลและธุรกรรมอิเล็กทรอนิกส์","ms":"Akta No. 1 Tahun 2024 tentang Pindaan Kedua Akta No. 11 Tahun 2008 tentang Maklumat dan Transaksi Elektronik"},"level":"law","status":"active","docNumber":"Undang-Undang Nomor 1 Tahun 2024","issuingBody":"印度尼西亚官方发布渠道","promulgatedDate":"2024-01-02","completenessNote":"全文，共 10 条；取自《东盟法律分类》归档中的 TXT 原件，逐字未改写。","country":"ID","countryName":"印度尼西亚","layer":"intl","articles":[{"id":"ID-H052-A1","no":1,"noLabel":{"en":"Article 1","zh":"第 1 条"},"text":{"id":"bahwa untuk menjaga ruang digital Indonesia yang bersih, sehat, beretika, produktif, dan berkeadilan, perlu diatur pemanfaatan Teknologi Informasi dan Transaksi Elektronik yang memberikan kepastian hukum, keadilan, dan melindungi kepentingan umum dari segala jenis gangguan sebagai akibat penyalahgunaan Informasi Elektronik, Dokumen Elektronik, Teknologi Informasi, dan/atau Transaksi Elektronik yang mengganggu ketertiban umum;"}},{"id":"ID-H052-A2","no":2,"noLabel":{"en":"Article 2","zh":"第 2 条"},"text":{"id":"bahwa beberapa ketentuan dalam Undang-Undang Nomor 11 Tahun 2008 tentang Informasi dan Transaksi Elektronik sebagaimana telah diubah dengan Undang-Undang Nomor 19 Tahun 2016 tentang Perubahan atas Undang-Undang Nomor 11 Tahun 2008 tentang Informasi dan Transaksi Elektronik, dalam pelaksanaannya masih menimbulkan multitafsir dan kontroversi di masyarakat sehingga perlu dilakukan perubahan untuk mewujudkan rasa keadilan masyarakat dan kepastian hukum;"}},{"id":"ID-H052-A3","no":3,"noLabel":{"en":"Article 3","zh":"第 3 条"},"text":{"id":"bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu membentuk Undang-Undang tentang Perubahan Kedua atas Undang-Undang Nomor 11 Tahun 2008 tentang Informasi dan Transaksi Elektronik;"}}],"pack":"id-p03"};
  FT["ID-H053"] = {"id":"ID-H053","coverage":"full","language":"id","sourceName":"印度尼西亚官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":25,"structureMode":"ARTICLE","title":{"zh":"印度尼西亚共和国1945年宪法（第三次修正）","en":"the 1945 Constitution of the Republic of Indonesia (Third Amendment)","orig":"Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 (Perubahan Ketiga)","id":"Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 (Perubahan Ketiga)","vi":"Hiến pháp nước Cộng hòa Indonesia năm 1945 (Sửa đổi Lần thứ ba)","th":"รัฐธรรมนูญแห่งสาธารณรัฐอินโดนีเซีย ค.ศ. 1945 (แก้ไขครั้งที่สาม)","ms":"Perlembagaan Negara Republik Indonesia 1945 (Pindaan Ketiga)"},"level":"law","status":"active","issuingBody":"印度尼西亚官方发布渠道","completenessNote":"全文，共 25 条；取自《东盟法律分类》归档中的 PDF 原件，逐字未改写。","country":"ID","countryName":"印度尼西亚","layer":"intl","articles":[{"id":"ID-H053-A7","no":7,"noLabel":{"en":"Article 7C","zh":"第 7C 条"},"text":{"id":"B Ayat (1), (2), (3), (4), (5), (6) dan (7); Pasal 7C, Pasal 8 Ayat (1) dan (2), Pasal 11\nAyat (2) dan (3); Pasal 17 Ayat (4), Bab VIIA, Pasal 22C Ayat (1), (2), (3) dan (4); Pasal 22D Ayat (1), (2), (3) dan (4); Bab VIIB, Pasal 22E ayat (1), (2), (3), (4), (5) dan (6);Pasal 23\nAyat (1), (2) dan (3); Pasal 23A; Pasal 23C; Bab VIIIA, Pasal 23E Ayat (1), (2) dan (3);"}},{"id":"ID-H053-A23","no":23,"noLabel":{"en":"Article 23G","zh":"第 23G 条"},"text":{"id":"F Ayat (1) dan (2); Pasal 23G Ayat (1) dan (2); Pasal 24 Ayat (1) dan (2), Pasal 24A Ayat (1), (2), (3), (4) dan (5); Pasal 24B Ayat (1), (2), (3) dan (4); dan Pasal 24C Ayat\n(1), (2), (3), (4), (5) dan (6) Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 sehingga selengkapnya menjadi berbunyi sebagai berikut:"}},{"id":"ID-H053-A1","no":1,"noLabel":{"en":"Article 1","zh":"第 1 条"},"text":{"id":"(2) Kedaulatan berada di tangan rakyat dan dilaksanakan menurut Undang-Undang Dasar.\n(3) Negara Indonesia adalah negara hukum."},"partIndex":2},{"id":"ID-H053-A3","no":3,"noLabel":{"en":"Article 3","zh":"第 3 条"},"text":{"id":"(1) Majelis Permusyawaratan Rakyat berwenang mengubah dan menetapkan Undang- Undang Dasar.\n(3) Majelis Permusyawaratan Rakyat melantik Presiden dan/atau Wakil Presiden.\n(4) Majelis Permusyawaratan Rakyat hanya dapat memberhentikan Presiden dan/atau Wakil Presiden dalam masa jabatannya menurut Undang-Undang Dasar."},"partIndex":2},{"id":"ID-H053-A6","no":6,"noLabel":{"en":"Article 6A","zh":"第 6A 条"},"text":{"id":"(1) Calon Presiden dan calon Wakil Presiden harus seorang warga negara Indonesia sejak kelahirannya dan tidak per nah menerima kewarganegaraan lain karena kehendaknya sendiri, tidak pernah mengkhianati negara, serta mampu secara rohani  dan jasmani untuk melaksanakan tugas dan kewajiban sebagai Presiden dan Wakil     Presiden.\n(2) Syarat-syarat untuk menjadi Presiden dan Wakil Presiden diatur lebih lanjut dengan undang-undang."},"partIndex":2},{"id":"ID-H053-A6-d2","no":6,"noLabel":{"en":"Article 6A","zh":"第 6A 条"},"text":{"id":"A\n(1) Presiden dan Wakil Presiden dipilih dalam satu pasangan secara langsung oleh rakyat.\n(2) Pasangan calon Presiden dan Wakil Presiden diusulkan oleh partai politik atau gabungan partai politik peserta pemilihan umum sebelum pelaksanaan pemilihan umum.\n(3) Pasangan calon Presiden dan Wakil Presiden yang mendapatkan suara lebih dari lima puluh persen dari jumlah suara dalam pemilihan umum dengan sedikitnya dua puluh persen suara di setiap provinsi yang tersebar di lebih dari setengah jumlah provinsi di Indonesia, dilantik menjadi Presiden dan Wakil Presiden.\n(5) Tata cara pelaksanaan pemilihan Presiden dan Wakil Presiden lebih lanjut diatur dalam undang-undang."},"dupIndex":2,"partIndex":2},{"id":"ID-H053-A7-d2","no":7,"noLabel":{"en":"Article 7C","zh":"第 7C 条"},"text":{"id":"A Presiden dan/atau Wakil Presiden dapat diberhentikan dalam masa jabatannya oleh Majelis Permusyawaratan Rakyat atas usul Dewan Perwakilan Rakyat, baik apabila terbukti telah melakukan pelanggaran hukum berupa pengkhianatan terhadap negara, korupsi, penyuapan, tindak pidana berat lainnya, atau perbuatan tercela maupun apabila terbukti tidak lagi memenuhi syarat sebagai Presiden dan/atau Wakil Presiden."},"dupIndex":2,"partIndex":2},{"id":"ID-H053-A7-d3","no":7,"noLabel":{"en":"Article 7C","zh":"第 7C 条"},"text":{"id":"B\n(1) Usul pemberhentian Presiden dan/atau Wakil Presiden dapat diajukan oleh Dewan Perwakilan Rakyat kepada Majelis Permusyawaratan Rakyat hanya dengan terlebih dahulu mengajukan permintaan kepada Mahkamah Konstitusi untuk memeriksa, mengadili, dan memutus pendapat Dewan Perwakilan Rakyat bahwa Presiden dan/atau Wakil Presiden telah melakukan pelanggaran hukum berupa pengkhianatan terhadap negara, korupsi, penyuapan, tindak pidana berat lainnya, atau perbuatan tercela; dan/atau pendapat bahwa Presiden dan/atau Wakil Presiden     tidak lagi memenuhi syarat sebagai Presiden dan/atau Wakil Presiden.\n(2) Pendapat Dewan Perwakilan Rakyat bahwa Presiden dan/atau Wakil Presiden telah melakukan pelanggaran hukum tersebut ataupun telah tidak lagi memenuhi syarat sebagai Presiden dan/atau Wakil Presiden adalah dalam rangka pelaksanaan fungsi pengawasan Dewan Perwakilan Rakyat.\n(3) Pengajuan permintaan Dewan Perwakilan Rakyat  kepada Mahkamah Konstitusi  hanya dapat dilakukan dengan dukungan sekurang-kurangnya 2/3 dari jumlah anggota Dewan Perwakilan Rakyat yang hadir dalam sidang paripurna yang dihadiri oleh sekurang-kurangnya 2/3 dari jumlah anggota Dewan Perwakilan Rakyat.\n(4) Mahkamah Konstitusi wajib memeriksa, mengadili, dan memutus dengan seadil-adilnya terhadap pendapat Dewan Perwakilan Rakyat tersebut paling lama sembilan   puluh hari setelah permintaan Dewan Perwakilan Rakyat itu diterima oleh Mahkamah Konstitusi.\n(5) Apabila Mahkamah Konstitusi memutuskan bahwa Presiden dan/atau Wakil Presiden terbukti melakukan pelanggaran hukum berupa pengkhianatan terhadap negara, korupsi, penyuapan, tindak pidana berat lainnya, atau perbuatan tercela; dan/atau terbukti bahwa Presiden dan/atau Wakil Presiden tidak lagi memenuhi  syarat sebagai Presiden dan/atau Wakil Presiden, Dewan Perwakilan Rakyat menyelenggarakan sidang paripurna untuk meneruskan usul pemberhentian Presiden dan/atau Wakil Presiden kepada Majelis Permusyawaratan Rakyat.\n(6) Majelis Permusyawaratan Rakyat wajib menyelenggarakan sidang untuk  memutuskan usul Dewan Perwakilan Rakyat tersebut paling lambat tiga puluh hari sejak Majelis Permusyawaratan Rakyat menerima usul tersebut.\n(7) Keputusan Majelis Permusyawaratan Rakyat atas usul pemberhentian Presiden dan/atau Wakil Presiden harus diambil dalam rapat paripurna Majelis Permusyawaratan Rakyat yang dihadiri oleh sekurang-kurangnya 3/4 dari jumlah anggota dan disetujui oleh sekurang-kurangnya 2/3 dari jumlah anggota yang hadir, setelah Presiden dan/atau Wakil Presiden diberi kesempatan menyampaikan     penjelasan dalam rapat paripurna Majelis Permusyawaratan Rakyat."},"dupIndex":3,"partIndex":2},{"id":"ID-H053-A7-d4","no":7,"noLabel":{"en":"Article 7C","zh":"第 7C 条"},"text":{"id":"C Presiden tidak dapat membekukan dan/atau membubarkan Dewan Perwakilan Rakyat."},"dupIndex":4,"partIndex":2},{"id":"ID-H053-A8","no":8,"noLabel":{"en":"Article 8","zh":"第 8 条"},"text":{"id":"(1) Jika Presiden mangkat, berhenti, diberhentikan, atau tidak dapat melakukan kewajibannya dalam masa jabatannya, ia digantikan oleh Wakil Presiden sampai habis masa jabatannya.\n(2) Dalam hal terjadi kekosongan Wakil Presiden, selambat-lambatnya dalam waktu enam puluh hari, Majelis Permusyawaratan Rakyat menyelenggarakan sidang untuk  memilih Wakil Presiden dari dua calon yang diusulkan oleh Presiden."},"partIndex":2},{"id":"ID-H053-A11","no":11,"noLabel":{"en":"Article 11","zh":"第 11 条"},"text":{"id":"(2) Presiden dalam membuat perjanjian internas ional lainnya yang menimbulkan akibat yang luas dan mendasar bagi kehidupan rakyat yang terkait dengan beban keuangan negara, dan/atau mengharuskan perubahan atau pembentukan undang-undang harus dengan persetujuan Dewan Perwakilan Rakyat.\n(3) Ketentuan lebih lanjut tentang perjanjian internasional diatur dengan undang-undang."},"partIndex":2},{"id":"ID-H053-A17","no":17,"noLabel":{"en":"Article 17","zh":"第 17 条"},"text":{"id":"(4) Pembentukan, pengubahan, dan pembubaran kementerian negara diatur dalam undang-undang.\nBAB VIIA\nDEWAN PERWAKILAN DAERAH"},"partIndex":2},{"id":"ID-H053-A22","no":22,"noLabel":{"en":"Article 22E","zh":"第 22E 条"},"text":{"id":"C\n(1) Anggota Dewan Perwakilan Daerah dipilih dari setiap provinsi melalui pemilihan  umum.\n(2) Anggota Dewan Perwakilan Daerah dari setiap provinsi jumlahnya sama dan jumlah seluruh anggota Dewan Perwakilan Daerah itu tidak lebih dari sepertiga jumlah anggota Dewan Perwakilan Rakyat.\n(3) Dewan Perwakilan Daerah bersidang sedikitnya sekali dalam setahun.\n(4) Susunan dan kedudukan Dewan Perwakilan Daerah diatur dengan undang-undang."},"partIndex":2},{"id":"ID-H053-A22-d2","no":22,"noLabel":{"en":"Article 22E","zh":"第 22E 条"},"text":{"id":"D\n(1) Dewan Perwakilan Daerah dapat mengajukan kepada Dewan Perwakilan Rakyat rancangan undang-undang yang berkaitan dengan otonomi daerah, hubungan pusat     dan daerah, pembentukan dan pemekaran serta penggabungan daerah, pengelolaan sumber daya alam dan sumber  daya ekonomi lainnya, serta yang berkaitan dengan perimbangan keuangan pusat dan daerah.\n(2) Dewan Perwakilan Daerah ikut membahas rancangan undang-undang yang  berkaitan dengan otonomi daerah; hubungan pusat dan daerah; pembentukan, pemekaran, dan penggabungan daerah; pengelolaan sumber daya alam dan sumber daya ekonomi lainnya, serta perimbangan keuangan pusat dan daerah; serta memberikan pertimbangan kepada Dewan Perwakilan Rakyat atas rancangan undang-undang anggaran pendapatan dan belanja negara dan rancangan undang-undang yang berkaitan dengan pajak, pendidikan, dan agama.\n(3) Dewan Perwakilan Daerah dapat melakukan pengawasan atas pelaksanaan undang-undang mengenai : otonomi daerah, pembentukan, pemekaran dan penggabungan daerah, hubungan pusat dan daerah, pengelolaan sumber daya alam dan sumber  daya ekonomi lainnya, pelaksanaan anggaran pendapatan dan belanja negara, pajak, pendidikan, dan agama serta menyampaikan hasil pengawasannya itu kepada Dewan Perwakilan Rakyat sebagai bahan pertimbangan untuk ditindaklanjuti.\n(4) Anggota Dewan Perwakilan Daerah dapat diberhentikan dari jabatannya, yang syarat-syarat dan tata caranya diatur dalam undang-undang.\nBAB VIIB\nPEMILIHAN UMUM"},"dupIndex":2,"partIndex":2},{"id":"ID-H053-A22-d3","no":22,"noLabel":{"en":"Article 22E","zh":"第 22E 条"},"text":{"id":"E\n(1) Pemilihan umum dilaksanakan secara langsung, umum, bebas, rahasia, jujur, dan adil setiap lima tahun sekali.\n(2) Pemilihan umum diselenggarakan untuk memilih anggota Dewan Perwakilan Rakyat, Dewan Perwakilan Daerah, Presiden dan Wakil Presiden dan Dewan     Perwakilan Rakyat Daerah.\n(3) Peserta pemilihan umum untuk memilih anggota Dewan Perwakilan Rakyat dan anggota Dewan Perwakilan Rakyat Daerah adalah partai politik.\n(4) Peserta pemilihan umum untuk memilih anggota Dewan Perwakilan Daerah adalah perseorangan.\n(5) Pemilihan umum diselenggarakan oleh suatu komisi pemilihan umum yang bersifat nasional, tetap, dan mandiri.\n(6) Ketentuan lebih lanjut tentang pemilihan umum diatur dengan undang-undang."},"dupIndex":3,"partIndex":2},{"id":"ID-H053-A23-d2","no":23,"noLabel":{"en":"Article 23G","zh":"第 23G 条"},"text":{"id":"(1) Anggaran pendapatan dan belanja negara sebagai wujud dari pengelolaan keuangan negara ditetapkan setiap tahun dengan undang-undang dan dilaksanakan secara terbuka dan bertanggung jawab untuk sebesar-besarnya kemakmuran rakyat.\n(2) Rancangan undang-undang anggaran pendapatan dan belanja negara diajukan oleh Presiden untuk dibahas bersama Dewan Perwakilan Rakyat dengan memperhatikan pertimbangan Dewan Perwakilan Daerah.\n(3) Apabila Dewan Perwakilan Rakyat tidak menyetujui rancangan anggaran pendapatan dan belanja negara yang diusulkan oleh Presiden, Pemerintah menjalankan Anggaran Pendapatan dan Belanja Negara tahun yang lalu."},"dupIndex":2,"partIndex":2},{"id":"ID-H053-A23-d3","no":23,"noLabel":{"en":"Article 23G","zh":"第 23G 条"},"text":{"id":"A Pajak dan pungutan lain yang bersifat memaksa untuk keperluan negara diatur dengan undang-undang."},"dupIndex":3,"partIndex":2},{"id":"ID-H053-A23-d4","no":23,"noLabel":{"en":"Article 23G","zh":"第 23G 条"},"text":{"id":"C Hal-hal lain mengenai keuangan negara diatur dengan undang-undang.\nBAB VIIIA\nBADAN PEMERIKSA KEUANGAN"},"dupIndex":4,"partIndex":2},{"id":"ID-H053-A23-d5","no":23,"noLabel":{"en":"Article 23G","zh":"第 23G 条"},"text":{"id":"E\n(1) Untuk memeriksa pengelolaan dan tanggung jawab tentang keuangan negara diadakan satu Badan Pemeriksa Keuangan yang bebas dan mandiri.\n(2) Hasil pemeriksaan keuangan negara diserahkan kepada Dewan Perwakilan Rakyat, Dewan Perwakilan Daerah, dan Dewan Perwakilan Rakyat Daerah, sesuai dengan kewenangannya.\n(3) Hasil pemeriksaan tersebut ditindaklanjuti oleh lembaga perwakilan dan/atau badan sesuai dengan undang-undang."},"dupIndex":5,"partIndex":2},{"id":"ID-H053-A23-d6","no":23,"noLabel":{"en":"Article 23G","zh":"第 23G 条"},"text":{"id":"F\n(1) Anggota Badan Pemeriksa Keuangan dipilih oleh Dewan Perwakilan Rakyat     dengan memperhatikan pertimbangan Dewan Perw akilan Daerah dan diresmikan oleh Presiden.\n(2) Pimpinan Badan Pemeriksa Keuangan dipilih dari dan oleh anggota."},"dupIndex":6,"partIndex":2},{"id":"ID-H053-A23-d7","no":23,"noLabel":{"en":"Article 23G","zh":"第 23G 条"},"text":{"id":"G\n(1) Badan Pemeriksa Keuangan berkedudukan di ibu kota negara, dan memiliki perwakilan di setiap provinsi.\n(2) Ketentuan lebih lanjut mengenai Badan Pemeriksa Keuangan diatur dengan undang-undang."},"dupIndex":7,"partIndex":2},{"id":"ID-H053-A24","no":24,"noLabel":{"en":"Article 24C","zh":"第 24C 条"},"text":{"id":"(1) Kekuasaan kehakiman merupakan kekuasaan yang merdeka untuk menyelenggarakan peradilan guna menegakkan hukum dan keadilan.\n(2) Kekuasaan kehakiman dilakukan oleh sebuah Mahkamah Agung dan badan peradilan yang berada di bawahnya dalam lingkungan peradilan umum, lingkungan  peradilan agama, lingkungan peradilan militer, lingkungan peradilan tata usaha negara, dan oleh sebuah Mahkamah Konstitusi."},"partIndex":2},{"id":"ID-H053-A24-d2","no":24,"noLabel":{"en":"Article 24C","zh":"第 24C 条"},"text":{"id":"A\n(1) Mahkamah Agung berwenang mengadili pada tingkat kasasi, menguji peraturan perundang-undangan di bawah undang-undang terhadap undang-undang, dan mempunyai wewenang lainnya yang diberikan oleh undang-undang.\n(2) Hakim agung harus memiliki integritas dan kepribadian yang tidak tercela, adil, profesional, dan berpengalaman di bidang hukum.\n(3) Calon hakim agung diusulkan Komisi Yudisial kepada Dewan Perwakilan Rakyat untuk mendapatkan persetujuan dan selanjutnya ditetapkan sebagai hakim agung oleh Presiden.\n(4) Ketua dan wakil ketua Mahkamah Agung dipilih dari dan oleh hakim agung.\n(5) Susunan, kedudukan, keanggotaan, dan hukum acara Mahkamah Agung serta badan peradilan di bawahnya diatur dengan undang-undang."},"dupIndex":2,"partIndex":2},{"id":"ID-H053-A24-d3","no":24,"noLabel":{"en":"Article 24C","zh":"第 24C 条"},"text":{"id":"B\n(1) Komisi Yudisial bersifat mandiri yang berwenang mengusulkan pengangkatan  hakim agung dan mempunyai wewenang lain dal am rangka menjaga dan menegakkan kehormatan, keluhuran martabat, serta perilaku hakim.\n(2) Anggota Komisi Yudisial harus mempunyai pengetahuan dan pengalaman di bidang hukum serta memiliki integritas dan kepribadian yang tidak tercela.\n(3) Anggota Komisi Yudisial diangkat dan diberhentikan oleh Presiden dengan persetujuan Dewan Perwakilan Rakyat.\n(4) Susunan, kedudukan, dan keanggotaan Komisi Yudisial diatur dengan undang-undang."},"dupIndex":3,"partIndex":2},{"id":"ID-H053-A24-d4","no":24,"noLabel":{"en":"Article 24C","zh":"第 24C 条"},"text":{"id":"C\n(1) Mahkamah Konstitusi berwenang mengadili pada tingkat pertama dan terakhir yang putusannya bersifat final untuk menguji undang-undang terhadap Undang-Undang Dasar, memutus sengketa kewenangan lembaga negara yang kewenangannya diberikan oleh Undang-Undang Dasar, memutus pembubaran partai politik, dan memutus perselisihan tentang hasil pemilihan umum.\n(2) Mahkamah Konstitusi wajib memberikan putusan atas pendapat Dewan Perwakilan Rakyat mengenai dugaan pelanggaran oleh Presiden dan/atau Wakil Presiden  menurut Undang-Undang Dasar.\n(3) Mahkamah Konstitusi mempunyai semb ilan orang anggota hakim konstitusi yang ditetapkan oleh Presiden, yang diajukan masing-masing tiga orang oleh Mahkamah Agung, tiga orang oleh Dewan Perwakilan Rakyat, dan tiga orang oleh Presiden.\n(4) Ketua dan Wakil Ketua Mahkamah Konstitusi dipilih dari dan oleh hakim konstitusi.\n(5) Hakim konstitusi harus memiliki integritas dan kepribadian yang tidak tercela, adil, negarawan yang menguasai konstitusi dan ketatanegaraan, serta tidak merangkap sebagai pejabat negara.\n(6) Pengangkatan dan pemberhentian hakim konstitusi, hukum acara serta ketentuan lainnya tentang Mahkamah Konstitusi diatur dengan undang-undang.\nNaskah perubahan ini merupakan bagian tak terpisahkan dari naskah Undang- Undang Dasar Negara Republik Indonesia Tahun 1945.\nPerubahan tersebut diputuskan dalam Rapat Paripurna Majelis Permusyawaratan Rakyat Republik Indonesia ke-7 (Lanjutan 2) tanggal 9 November 2001 Sidang Tahunan Majelis Permusyawaratan Rakyat Republik Indonesia, dan mulai berlaku pada tanggal ditetapkan.\nDitetapkan di Jakarta Pada tanggal 9 November 2001 MAJELIS PERMUSYAWARATAN RAKYAT REPUBLIK INDONESIA Ketua, Prof. Dr. H.M. Amien Rais Wakil Ketua, Prof. Dr. Ir. Ginandjar Kartasasmita Wakil Ketua, Ir. Sutjipto Wakil Ketua, Prof. Dr. Jusuf Amir Feisal, S.Pd.\nWakil Ketua,\nDrs. H.M. Husnie Thamrin\nWakil Ketua,\nDrs. H.A. Nazri Adlani\nWakil Ketua,\nAgus Widjojo"},"dupIndex":4,"partIndex":2}],"pack":"id-p03"};
  FT["ID-H054"] = {"id":"ID-H054","coverage":"full","language":"id","sourceName":"印度尼西亚官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":37,"structureMode":"ARTICLE","title":{"zh":"印度尼西亚共和国1945年宪法（原始文本）","en":"the 1945 Constitution of the Republic of Indonesia (Original Text)","orig":"Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 (Naskah Asli)","id":"Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 (Naskah Asli)","vi":"Hiến pháp nước Cộng hòa Indonesia năm 1945 (Bản gốc)","th":"รัฐธรรมนูญแห่งสาธารณรัฐอินโดนีเซีย ค.ศ. 1945 (ฉบับดั้งเดิม)","ms":"Perlembagaan Negara Republik Indonesia 1945 (Teks Asal)"},"level":"law","status":"active","issuingBody":"印度尼西亚官方发布渠道","completenessNote":"全文，共 37 条；取自《东盟法律分类》归档中的 PDF 原件，逐字未改写。","country":"ID","countryName":"印度尼西亚","layer":"intl","articles":[{"id":"ID-H054-A1","no":1,"noLabel":{"en":"Article 1","zh":"第 1 条"},"text":{"id":"(1) Negara Indonesia ialah Negara Kesatuan, yang berbentuk Republik.\n(2) Kedaulatan adalah di tangan rakyat, dan dilakukan sepenuhnya oleh Majelis Permusyawaratan Rakyat.\nBAB II\nMAJELIS PERMUSYAWARATAN RAKYAT"}},{"id":"ID-H054-A2","no":2,"noLabel":{"en":"Article 2","zh":"第 2 条"},"text":{"id":"(1) Majelis Permusyawaratan Rakyat terd iri atas anggota-anggota Dewan Perwakilan Rakyat, ditambah dengan utusan-utusan dari daerah-daerah dan golongan-golongan, menurut aturan yang ditetapkan dengan undang-undang.\n(2) Majelis Permusyawaratan Rakyat bersidang sedikitnya sekali dalam lima tahun di ibu kota negara.\n(3) Segala putusan Majelis Permusyawarat an Rakyat ditetapkan dengan suara yang terbanyak."}},{"id":"ID-H054-A3","no":3,"noLabel":{"en":"Article 3","zh":"第 3 条"},"text":{"id":"Majelis Permusyawaratan Rakyat menetapkan Undang-Undang Dasar dan garis-garis besar daripada haluan negara.\nBAB III\nKEKUASAAN PEMERINTAHAN NEGARA"}},{"id":"ID-H054-A4","no":4,"noLabel":{"en":"Article 4","zh":"第 4 条"},"text":{"id":"(1) Presiden Republik Indonesia memegang kekuasaan pemerintahan menurut Undang- Undang Dasar.\n(2) Dalam melakukan kewajibannya Presiden dibantu oleh satu orang Wakil Presiden."}},{"id":"ID-H054-A5","no":5,"noLabel":{"en":"Article 5","zh":"第 5 条"},"text":{"id":"(1) Presiden memegang kekuasaan membentuk undang-undang dengan persetujuan Dewan Perwakilan Rakyat.\n(2) Presiden menetapkan peraturan pemerintah untuk menjalankan undang-undang sebagaimana mestinya."}},{"id":"ID-H054-A6","no":6,"noLabel":{"en":"Article 6","zh":"第 6 条"},"text":{"id":"(1) Presiden ialah orang Indonesia asli.\n(2) Presiden dan Wakil Presiden dipilih oleh Majelis Permusyawaratan Rakyat dengan suara yang terbanyak."}},{"id":"ID-H054-A7","no":7,"noLabel":{"en":"Article 7","zh":"第 7 条"},"text":{"id":"Presiden dan Wakil Presiden memegang jabatannya selama masa lima tahun, dan sesudahnya dapat dipilih kembali."}},{"id":"ID-H054-A8","no":8,"noLabel":{"en":"Article 8","zh":"第 8 条"},"text":{"id":"Jika Presiden mangkat, berhenti, atau tidak  dapat melakukan kewajibannya dalam masa jabatannya, ia diganti oleh Wakil Presiden sampai habis waktunya."}},{"id":"ID-H054-A9","no":9,"noLabel":{"en":"Article 9","zh":"第 9 条"},"text":{"id":"Sebelum memangku jabatannya, Presiden dan Wakil Presiden bersumpah menurut agama, atau berjanji dengan sungguh-sungguh di hadapan Majelis Permusyawaratan Rakyat atau Dewan Perwakilan Rakyat sebagai berikut :\nSumpah Presiden (Wakil Presiden) :\n“Demi Allah, saya bersumpah akan memenuhi kewajiban Presiden Republik Indonesia (Wakil Presiden Republik Indonesia) dengan sebaik-baiknya dan seadil-adilnya, memegang teguh Undang-Undang Dasar dan menjalankan segala undang-undang dan peraturannya dengan selurus-lurusnya serta berbakti kepada Nusa dan Bangsa”.\nJanji Presiden (Wakil Presiden) :\n“Saya berjanji dengan sungguh-sungguh akan memenuhi kewajiban Presiden Republik Indonesia (Wakil Presiden R epublik Indonesia) dengan sebaik-baiknya dan seadil-adilnya, memegang teguh Undang-Undang Dasar dan menjalankan segala undang-undang dan peraturannya dengan selurus-lurusnya serta berbakti kepada Nusa dan Bangsa”."}},{"id":"ID-H054-A10","no":10,"noLabel":{"en":"Article 10","zh":"第 10 条"},"text":{"id":"Presiden memegang kekuasaan yang tertinggi atas Angkatan Darat, Angkatan Laut dan Angkatan Udara."}},{"id":"ID-H054-A11","no":11,"noLabel":{"en":"Article 11","zh":"第 11 条"},"text":{"id":"Presiden dengan persetujuan Dewan Perwakilan Rakyat menyatakan perang, membuat perdamaian dan perjanjian dengan negara lain."}},{"id":"ID-H054-A12","no":12,"noLabel":{"en":"Article 12","zh":"第 12 条"},"text":{"id":"Presiden menyatakan keadaan bahaya. Syar at-syarat dan akibatnya keadaan bahaya ditetapkan dengan undang-undang."}},{"id":"ID-H054-A13","no":13,"noLabel":{"en":"Article 13","zh":"第 13 条"},"text":{"id":"(1) Presiden mengangkat duta dan konsul.\n(2) Presiden menerima duta negara lain."}},{"id":"ID-H054-A14","no":14,"noLabel":{"en":"Article 14","zh":"第 14 条"},"text":{"id":"Presiden memberi grasi, amnesti, abolisi dan rehabilitasi."}},{"id":"ID-H054-A15","no":15,"noLabel":{"en":"Article 15","zh":"第 15 条"},"text":{"id":"Presiden memberi gelaran, tanda jasa dan lain-lain tanda kehormatan.\nBAB IV\nDEWAN PERTIMBANGAN AGUNG"}},{"id":"ID-H054-A16","no":16,"noLabel":{"en":"Article 16","zh":"第 16 条"},"text":{"id":"(1) Susunan Dewan Pertimbangan Agung ditetapkan dengan undang-undang.\n(2) Dewan ini berkewajiban memberi jawab atas pertanyaan Presiden dan berhak memajukan usul kepada pemerintah.\nBAB V\nKEMENTERIAN NEGARA"}},{"id":"ID-H054-A17","no":17,"noLabel":{"en":"Article 17","zh":"第 17 条"},"text":{"id":"(1) Presiden dibantu oleh menteri-menteri negara.\n(2) Menteri-menteri itu diangkat dan diperhentikan oleh Presiden.\n(3) Menteri-menteri itu memimpin departemen pemerintah.\nBAB VI\nPEMERINTAH DAERAH"}},{"id":"ID-H054-A18","no":18,"noLabel":{"en":"Article 18","zh":"第 18 条"},"text":{"id":"Pembagian daerah Indonesia atas daerah besar dan kecil, dengan bentuk susunan pemerintahannya ditetapkan dengan undang-undang, dengan memandang dan mengingati dasar permusyawaratan dalam sistem pemerintahan negara, dan hak-hak asal-usul dalam daerah-daerah yang bersifat istimewa.\nBAB VII\nDEWAN PERWAKILAN RAKYAT"}},{"id":"ID-H054-A19","no":19,"noLabel":{"en":"Article 19","zh":"第 19 条"},"text":{"id":"(1) Susunan Dewan Perwakilan Rakyat ditetapkan dengan undang-undang.\n(2) Dewan Perwakilan Rakyat bersidang sedikitnya sekali dalam setahun."}},{"id":"ID-H054-A20","no":20,"noLabel":{"en":"Article 20","zh":"第 20 条"},"text":{"id":"(1) Tiap-tiap undang-undang menghendaki persetujuan Dewan Perwakilan Rakyat.\n(2) Jika sesuatu rancangan undang-undang tidak mendapat persetujuan Dewan Perwakilan Rakyat, maka rancangan tadi tidak boleh dimajukan lagi dalam persidangan Dewan Perwakilan Rakyat masa itu."}},{"id":"ID-H054-A21","no":21,"noLabel":{"en":"Article 21","zh":"第 21 条"},"text":{"id":"(1) Anggota-anggota Dewan Perwakilan Rakyat berhak memajukan rancangan undang-undang.\n(2) Jika rancangan itu, meskipun disetujui oleh Dewan Perwakilan Rakyat, tidak disahkan oleh Presiden, maka rancangan tadi tidak boleh dimajukan lagi dalam persidangan Dewan Perwakilan Rakyat masa itu."}},{"id":"ID-H054-A22","no":22,"noLabel":{"en":"Article 22","zh":"第 22 条"},"text":{"id":"(1) Dalam hal ihwal kegentingan yang memaksa, Presiden berhak menetapkan peraturan pemerintah sebagai pengganti undang-undang.\n(2) Peraturan pemerintah itu harus menda pat persetujuan Dewan Perwakilan Rakyat dalam persidangan yang berikut.\n(3) Jika tidak mendapat persetujuan, maka peraturan pemerintah itu harus dicabut.\nBAB VIII\nHAL KEUANGAN"}},{"id":"ID-H054-A23","no":23,"noLabel":{"en":"Article 23","zh":"第 23 条"},"text":{"id":"(1) Anggaran pendapatan dan belanja ditetapkan tiap-tiap tahun dengan undang-undang.\nApabila Dewan Perwakilan Rakyat tidak  menyetujui anggaran yang diusulkan pemerintah, maka pemerintah menjalankan anggaran tahun yang lalu.\n(2) Segala pajak untuk keperluan negara berdasarkan undang-undang.\n(3) Macam dan harga mata uang ditetapkan dengan undang-undang.\n(4) Hal keuangan negara selanjutnya diatur dengan undang-undang.\n(5) Untuk memeriksa tanggung jawab tentang keuangan negara diadakan suatu Badan Pemeriksa Keuangan, yang peraturannya ditetapkan dengan undang-undang. Hasil pemeriksaan itu diberitahukan kepada Dewan Perwakilan rakyat.\nBAB IX\nKEKUASAAN KEHAKIMAN"}},{"id":"ID-H054-A24","no":24,"noLabel":{"en":"Article 24","zh":"第 24 条"},"text":{"id":"(1) Kekuasaan kehakiman dilakukan oleh sebuah Mahkamah Agung dan lain-lain badan kehakiman menurut undang-undang.\n(2) Susunan dan kekuasaan badan-badan kehakiman itu diatur dengan undang-undang."}},{"id":"ID-H054-A25","no":25,"noLabel":{"en":"Article 25","zh":"第 25 条"},"text":{"id":"Syarat-syarat untuk menjadi dan untuk diperhentikan sebagai hakim ditetapkan dengan undang-undang.\nBAB X\nWARGA NEGARA"}},{"id":"ID-H054-A26","no":26,"noLabel":{"en":"Article 26","zh":"第 26 条"},"text":{"id":"(1) Yang menjadi warga negara ialah orang-orang bangsa Indonesia asli dan orang-orang bangsa lain yang disahkan dengan undang-undang sebagai warga negara.\n(2) Syarat-syarat yang mengenai kewa rganegaraan ditetapkan dengan undang-undang."}},{"id":"ID-H054-A27","no":27,"noLabel":{"en":"Article 27","zh":"第 27 条"},"text":{"id":"(1) Segala warga negara bersamaan kedudukannya di dalam hukum dan pemerintahan dan wajib menjunjung hukum dan pemerintahan itu dengan tidak ada kecualinya.\n(2) Tiap-tiap warga negara berhak atas pekerjaan dan penghidupan yang layak bagi kemanusiaan."}},{"id":"ID-H054-A28","no":28,"noLabel":{"en":"Article 28","zh":"第 28 条"},"text":{"id":"Kemerdekaan berserikat dan berkumpul, meng eluarkan pikiran dengan lisan dan tulisan dan sebaganya ditetapkan dengan undang-undang.\nBAB XI\nA G A M A"}},{"id":"ID-H054-A29","no":29,"noLabel":{"en":"Article 29","zh":"第 29 条"},"text":{"id":"(1) Negara berdasar atas Ketuhanan Yang Maha Esa.\n(2) Negara menjamin kemerdekaan tiap-tiap penduduk untuk memeluk agamanya masing-masing dan untuk beribadat menurut agamanya dan kepercayaannya itu.\nBAB XII\nPERTAHANAN NEGARA"}},{"id":"ID-H054-A30","no":30,"noLabel":{"en":"Article 30","zh":"第 30 条"},"text":{"id":"(1) Tiap-tiap warga negara berhak dan wajib ikut serta dalam usaha pembelaan negara.\n(2) Syarat-syarat tentang pembelaan diatur dengan undang-undang.\nBAB XIII\nP E N D I D I K A N"}},{"id":"ID-H054-A31","no":31,"noLabel":{"en":"Article 31","zh":"第 31 条"},"text":{"id":"(1) Tiap-tiap warga negara berhak mendapat pengajaran.\n(2) Pemerintah mengusahakan dan menyelenggar akan satu sistem pengajaran nasional, yang diatur dengan undang-undang."}},{"id":"ID-H054-A32","no":32,"noLabel":{"en":"Article 32","zh":"第 32 条"},"text":{"id":"Pemerintah memajukan kebudayaan nasional Indonesia.\nBAB XIV\nKESEJAHTERAAN SOSIAL"}},{"id":"ID-H054-A33","no":33,"noLabel":{"en":"Article 33","zh":"第 33 条"},"text":{"id":"(1) Perekonomian disusun sebagai usaha ber sama berdasar atas asas kekeluargaan.\n(2) Cabang-cabang produksi yang penting bagi negara dan yang menguasai hajat hidup orang banyak dikuasai oleh negara.\n(3) Bumi dan air dan kekayaan alam yang terkandung di dalamnya dikuasai oleh negara dan dipergunakan untuk sebesar-besar kemakmuran rakyat."}},{"id":"ID-H054-A34","no":34,"noLabel":{"en":"Article 34","zh":"第 34 条"},"text":{"id":"Fakir miskin dan anak-anak yang terlantar dipelihara oleh negara.\nBAB XV\nBENDERA DAN BAHASA"}},{"id":"ID-H054-A35","no":35,"noLabel":{"en":"Article 35","zh":"第 35 条"},"text":{"id":"Bendera Negara Indonesia ialah Sang Merah Putih."}},{"id":"ID-H054-A36","no":36,"noLabel":{"en":"Article 36","zh":"第 36 条"},"text":{"id":"Bahasa Negara ialah Bahasa Indonesia.\nBAB XVI\nPERUBAHAN UNDANG-UNDANG DASAR"}},{"id":"ID-H054-A37","no":37,"noLabel":{"en":"Article 37","zh":"第 37 条"},"text":{"id":"(1) Untuk mengubah Undang-Undang Dasar se kurang-kurangnya 2/3 daripada jumlah anggota Majelis Permusyawaratan Rakyat harus hadir.\n(2) Putusan diambil dengan persetujuan sekurang-kurangnya 2/3 daripada jumlah anggota yang hadir.\nATURAN PERALIHAN\nPasal I\nPanitia Persiapan Kemerdekaan Indonesia mengatur dan menyelenggarakan kepindahan pemerintahan kepada Pemerintah Indonesia.\nPasal II\nSegala badan negara dan peraturan yang ada masih langsung berlaku, selama belum diadakan yang baru menurut Undang-Undang Dasar ini.\nPasal III\nUntuk pertama kali Presiden dan Wakil Presiden dipilih oleh Panitia Persiapan Kemerdekaan Indonesia.\nPasal IV\nSebelum Majelis Permusyawaratan Rakyat, Dewan Perwakilan Rakyat, dan Dewan Pertimbangan Agung dibentuk menurut Undang-Undang Dasar ini, segala kekuasaannya dijalankan oleh Presiden dengan bantuan sebuah komite nasional.\nATURAN TAMBAHAN\n(1) Dalam enam bulan sesudah akhirnya peperangan Asia Timur Raya, Presiden Indonesia mengatur dan menyelenggarakan segala hal yang ditetapkan dalam Undang-Undang Dasar ini.\n(2) Dalam enam bulan sesudah Majelis Permusyawaratan Rakyat dibentuk, Majelis itu bersidang untuk menetapkan Undang-Undang Dasar."}}],"pack":"id-p03"};
  FT["ID-H055"] = {"id":"ID-H055","coverage":"full","language":"id","sourceName":"印度尼西亚官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"电子信息与交易法","en":"Law No. 11 of 2008 on Electronic Information and Transactions","orig":"Undang-Undang Nomor 11 Tahun 2008 tentang Informasi dan Transaksi Elektronik","id":"Undang-Undang Nomor 11 Tahun 2008 tentang Informasi dan Transaksi Elektronik","vi":"Luật số 11 năm 2008 về Thông tin và Giao dịch Điện tử","th":"พระราชบัญญัติเลขที่ 11 ปี 2008 ว่าด้วยข้อมูลและธุรกรรมอิเล็กทรอนิกส์","ms":"Akta No. 11 Tahun 2008 tentang Maklumat dan Transaksi Elektronik"},"level":"law","status":"active","docNumber":"Undang-Undang Nomor 11 Tahun 2008","issuingBody":"印度尼西亚官方发布渠道","promulgatedDate":"2008-04-21","completenessNote":"全文，共 7 条；取自《东盟法律分类》归档中的 TXT 原件，逐字未改写。","country":"ID","countryName":"印度尼西亚","layer":"intl","articles":[{"id":"ID-H055-A1","no":1,"noLabel":{"en":"Article 1","zh":"第 1 条"},"text":{"id":"bahwa pembangunan nasional adalah suatu proses yang berkelanjutan yang harus senantiasa tanggap terhadap berbagai dinamika yang terjadi di masyarakat;"}},{"id":"ID-H055-A2","no":2,"noLabel":{"en":"Article 2","zh":"第 2 条"},"text":{"id":"bahwa globalisasi informasi telah menempatkan Indonesia sebagai bagian dari masyarakat informasi dunia sehingga mengharuskan dibentuknya pengaturan mengenai pengelolaan Informasi dan Transaksi Elektronik di tingkat nasional sehingga pembangunan Teknologi Informasi dapat dilakukan secara optimal, merata, dan menyebar ke seluruh lapisan masyarakat guna mencerdaskan kehidupan bangsa;"}},{"id":"ID-H055-A3","no":3,"noLabel":{"en":"Article 3","zh":"第 3 条"},"text":{"id":"bahwa perkembangan dan kemajuan Teknologi Informasi yang demikian pesat telah menyebabkan perubahan kegiatan kehidupan manusia dalam berbagai bidang yang secara langsung telah memengaruhi lahirnya bentuk-bentuk perbuatan hukum baru;"}},{"id":"ID-H055-A4","no":4,"noLabel":{"en":"Article 4","zh":"第 4 条"},"text":{"id":"bahwa penggunaan dan pemanfaatan Teknologi Informasi harus terus dikembangkan untuk menjaga, memelihara, dan memperkukuh persatuan dan kesatuan nasional berdasarkan Peraturan Perundang-undangan demi kepentingan nasional;"}},{"id":"ID-H055-A5","no":5,"noLabel":{"en":"Article 5","zh":"第 5 条"},"text":{"id":"bahwa pemanfaatan Teknologi Informasi berperan penting dalam perdagangan dan pertumbuhan perekonomian nasional untuk mewujudkan kesejahteraan masyarakat;"}},{"id":"ID-H055-A6","no":6,"noLabel":{"en":"Article 6","zh":"第 6 条"},"text":{"id":"bahwa pemerintah perlu mendukung pengembangan Teknologi Informasi melalui infrastruktur hukum dan pengaturannya sehingga pemanfaatan Teknologi Informasi dilakukan secara aman untuk mencegah penyalahgunaannya dengan memperhatikan nilai-nilai agama dan sosial budaya masyarakat Indonesia;"}},{"id":"ID-H055-A7","no":7,"noLabel":{"en":"Article 7","zh":"第 7 条"},"text":{"id":"bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, huruf b, huruf c, huruf d, huruf e, dan huruf f, perlu membentuk Undang-Undang tentang Informasi dan Transaksi Elektronik;\nPasal 5 ayat (1) dan Pasal 20 Undang-Undang Dasar Negara Republik IndonesiaTahun 1945;\nDengan Persetujuan Bersama\nDEWAN PERWAKILAN RAKYAT REPUBLIK INDONESIA\nDAN PRESIDEN REPUBLIK INDONESIA\nUNDANG-UNDANG TENTANG INFORMASI DAN TRANSAKSI ELEKTRONIK.\nCukup jelas.\nUndang-Undang ini memiliki jangkauan yurisdiksi tidak semata-mata untuk perbuatan hukum yang berlaku di Indonesia dan/atau dilakukan oleh warga negara Indonesia, tetapi juga berlaku untuk perbuatan hukum yang dilakukan di luar wilayah hukum (yurisdiksi) Indonesia baik oleh warga negara Indonesia maupun warga negara asing atau badan hukum Indonesia maupun badan hukum asing yang memiliki akibat hukum di Indonesia, mengingat pemanfaatan Teknologi Informasi untuk Informasi Elektronik dan Transaksi Elektronik dapat bersifat lintas teritorial atau universal.\nYang dimaksud dengan “merugikan kepentingan Indonesia” adalah meliputi tetapi tidak terbatas pada merugikan kepentingan ekonomi nasional, perlindungan data strategis, harkat dan martabat bangsa, pertahanan dan keamanan negara, kedaulatan negara, warga negara, serta badan hukum Indonesia.\n“Asas kepastian hukum” berarti landasan hukum bagi pemanfaatan Teknologi Informasi dan Transaksi Elektronik serta segala sesuatu yang mendukung penyelenggaraannya yang mendapatkan pengakuan hukum di dalam dan di luar pengadilan.\n“Asas manfaat” berarti asas bagi pemanfaatan Teknologi Informasi dan Transaksi Elektronik diupayakan untuk mendukung proses berinformasi sehingga dapat meningkatkan kesejahteraan masyarakat.\n“Asas kehati-hatian” berarti landasan bagi pihak yang bersangkutan harus memperhatikan segenap aspek yang berpotensi mendatangkan kerugian, baik bagi dirinya maupun bagi pihak lain dalam pemanfaatan Teknologi Informasi dan Transaksi Elektronik.\n“Asas iktikad baik” berarti asas yang digunakan para pihak dalam melakukan Transaksi Elektronik tidak bertujuan untuk secara sengaja dan tanpa hak atau melawan hukum mengakibatkan kerugian bagi pihak lain tanpa sepengetahuan pihak lain tersebut.\n“Asas kebebasan memilih teknologi atau netral teknologi” berarti asas pemanfaatan Teknologi Informasi dan Transaksi Elektronik tidak terfokus pada penggunaan teknologi tertentu sehingga dapat mengikuti perkembangan pada masa yang akan datang.\nCukup jelas.\nAyat 1 Cukup jelas.\nAyat 2 Cukup jelas.\nAyat 3 Cukup jelas.\nAyat 4\nHuruf a\nSurat yang menurut undang-undang harus dibuat tertulis meliputi tetapi tidak terbatas pada surat berharga, surat yang berharga, dan surat yang digunakan dalam proses penegakan hukum acara perdata, pidana, dan administrasi negara.\nHuruf b Cukup jelas.\nSelama ini bentuk tertulis identik dengan informasi dan/atau dokumen yang tertuang di atas kertas semata, padahal pada hakikatnya informasi dan/atau dokumen dapat dituangkan ke dalam media apa saja, termasuk media elektronik. Dalam lingkup Sistem Elektronik, informasi yang asli dengan salinannya tidak relevan lagi untuk dibedakan sebab Sistem Elektronik pada dasarnya beroperasi dengan cara penggandaan yang mengakibatkan informasi yang asli tidak dapat dibedakan lagi dari salinannya.\nKetentuan ini dimaksudkan bahwa suatu Informasi Elektronik dan/atau Dokumen Elektronik dapat digunakan sebagai alasan timbulnya suatu hak.\nCukup jelas.\nYang dimaksud dengan “informasi yang lengkap dan benar” meliputi:\na. informasi yang memuat identitas serta status subjek hukum dan kompetensinya, baik sebagai produsen, pemasok, penyelenggara maupun perantara;\nb. informasi lain yang menjelaskan hal tertentu yang menjadi syarat sahnya perjanjian serta menjelaskan barang dan/atau jasa yang ditawarkan, seperti nama, alamat, dan deskripsi barang/jasa.\nAyat 1 Sertifikasi Keandalan dimaksudkan sebagai bukti bahwa pelaku usaha yang melakukan perdagangan secara elektronik layak berusaha setelah melalui penilaian dan audit dari badan yang berwenang. Bukti telah dilakukan Sertifikasi Keandalan ditunjukkan dengan adanya logo sertifikasi berupa trust mark pada laman (home page) pelaku usaha tersebut.\nAyat 2 Cukup jelas.\nAyat 1 Undang-Undang ini memberikan pengakuan secara tegas bahwa meskipun hanya merupakan suatu kode, Tanda Tangan Elektronik memiliki kedudukan yang sama dengan tanda tangan manual pada umumnya yang memiliki kekuatan hukum dan akibat hukum. Persyaratan sebagaimana dimaksud dalam Pasal ini merupakan persyaratan minimum yang harus dipenuhi dalam setiap Tanda Tangan Elektronik. Ketentuan ini membuka kesempatan seluas-luasnya kepada siapa pun untuk mengembangkan metode, teknik, atau proses pembuatan Tanda Tangan Elektronik. Peraturan Pemerintah dimaksud, antara lain, mengatur tentang teknik, metode, sarana, dan proses pembuatan Tanda Tangan Elektronik.\nAyat 2 Peraturan Pemerintah dimaksud, antara lain, mengatur tentang teknik, metode, sarana, dan proses pembuatan Tanda Tangan Elektronik.\nCukup jelas.\nCukup jelas.\nInformasi sebagaimana dimaksud dalam Pasal ini adalah informasi yang minimum harus dipenuhi oleh setiap penyelenggara Tanda Tangan Elektronik.\nAyat 1 “Andal” artinya Sistem Elektronik memiliki kemampuan yang sesuai dengan kebutuhan penggunaannya.\n“Aman” artinya Sistem Elektronik terlindungi secara fisik dan nonfisik.\n“Beroperasi sebagaimana mestinya” artinya Sistem Elektronik memiliki kemampuan sesuai dengan spesifikasinya.\nAyat 2 “Bertanggung jawab” artinya ada subjek hukum yang bertanggung jawab secara hukum terhadap Penyelenggaraan Sistem Elektronik tersebut.\nAyat 3 Cukup jelas.\nCukup jelas."}}],"pack":"id-p03"};
  FT["ID-H056"] = {"id":"ID-H056","coverage":"full","language":"id","sourceName":"印度尼西亚官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":1,"structureMode":"WHOLE","title":{"zh":"个人数据保护法","en":"Law No. 27 of 2022 on Personal Data Protection","orig":"Undang-Undang Nomor 27 Tahun 2022 tentang Pelindungan Data Pribadi","id":"Undang-Undang Nomor 27 Tahun 2022 tentang Pelindungan Data Pribadi","vi":"Luật số 27 năm 2022 về Bảo vệ Dữ liệu Cá nhân","th":"พระราชบัญญัติเลขที่ 27 ปี 2022 ว่าด้วยการคุ้มครองข้อมูลส่วนบุคคล","ms":"Akta No. 27 Tahun 2022 tentang Perlindungan Data Peribadi"},"level":"law","status":"active","docNumber":"Undang-Undang Nomor 27 Tahun 2022","issuingBody":"印度尼西亚官方发布渠道","promulgatedDate":"2022-10-17","completenessNote":"文本未能可靠切分为条文（或原件为目录式排版），按整篇收录，未作改写。","country":"ID","countryName":"印度尼西亚","layer":"intl","articles":[{"id":"ID-H056-A1","no":1,"noLabel":{"en":"Article 1","zh":"第 1 条"},"text":{"id":"SOURCE_URL: https://jdih.komdigi.go.id/produk_hukum/view/id/832/t/undangundang+nomor+27+tahun+2022 TITLE_ORIGINAL: Undang-Undang Nomor 27 Tahun 2022 tentang Pelindungan Data Pribadi LAW_NUMBER: Undang-Undang Nomor 27 Tahun 2022 ENACTED: 2022-10-17 EFFECTIVE: 未确认 AMENDED: 未确认 VERSION: 未确认 LANG: id STATUS: partial MISSING: 本次 web_fetch 返回内容在 Penjelasan 段（Pasal 4 关于 data pribadi 特定类型之说明）中途被通道截断（返回末尾为 \"Content truncated\"）；页面 \"Isi Dokumen\"（法条正文 Pasal 1-76 及全文）未出现在返回窗口内。已获取：metadata（Tanggal Penetapan/Pengundangan 17-10-2022、LN 2022 (196): 50 hlm.）、Navigasi Pasal 全表、menimbang/mengingat、Penjelasan 前段（asas a-h、Pasal 4 部分）。另：站点导航栏与页脚样板文字（非正文）未重复录入。\n--- CONTENT BELOW --- # Undang-Undang Nomor 27 Tahun 2022 tentang Pelindungan Data Pribadi Judul Undang-Undang Nomor 27 Tahun 2022 Tipe Dokumen Peraturan Perundang-undangan Nomor 27 Tahun 2022 Tanggal Penetapan 17-10-2022 Tanggal Pengundangan 17-10-2022 Tempat Penetapan Jakarta Sumber LN 2022 (196): 50 hlm.\nBahasa\nIndonesia\nLokasi\nBIRO HUKUM KOMINFO\nBidang Hukum\nHukum Administrasi Negara\nT.E.U BADAN | Nama Pengarang | Tipe Pengarang | Jenis Pengarang | | --- | --- | --- | | Indonesia | Badan Organisasi | Pengarang Utama | SUBJEK PELINDUNGAN - DATA PRIBADI ###### Peraturan Terkait Data belum Tersedia ###### Dokumen Terkait Data belum Tersedia ###### Peraturan Pelaksanaan Data belum Tersedia ###### Hasil Uji Materi Data belum Tersedia ###### Navigasi Pasal -   menimbang -   mengingat -   menetapkan -   Pasal 1 -   Pasal 2 -   Pasal 3 -   Pasal 4 -   Pasal 5 -   Pasal 6 -   Pasal 7 -   Pasal 8 -   Pasal 9 -   Pasal 10 -   Pasal 11 -   Pasal 12 -   Pasal 13 -   Pasal 14 -   Pasal 15 -   Pasal 16 -   Pasal 17 -   Pasal 18 -   Pasal 19 -   Pasal 20 -   Pasal 21 -   Pasal 22 -   Pasal 23 -   Pasal 24 -   Pasal 25 -   Pasal 26 -   Pasal 27 -   Pasal 28 -   Pasal 29 -   Pasal 30 -   Pasal 31 -   Pasal 32 -   Pasal 33 -   Pasal 34 -   Pasal 35 -   Pasal 36 -   Pasal 37 -   Pasal 38 -   Pasal 39 -   Pasal 40 -   Pasal 41 -   Pasal 42 -   Pasal 43 -   Pasal 44 -   Pasal 45 -   Pasal 46 -   Pasal 47 -   Pasal 48 -   Pasal 49 -   Pasal 50 -   Pasal 51 -   Pasal 52 -   Pasal 53 -   Pasal 54 -   Pasal 55 -   Pasal 56 -   Pasal 57 -   Pasal 58 -   Pasal 59 -   Pasal 60 -   Pasal 61 -   Pasal 62 -   Pasal 63 -   Pasal 64 -   Pasal 65 -   Pasal 66 -   Pasal 67 -   Pasal 68 -   Pasal 69 -   Pasal 70 -   Pasal 71 -   Pasal 72 -   Pasal 73 -   Pasal 74 -   Pasal 75 -   Pasal 76 -   Pasal 65 -   Pasal 66 -   Pasal 67 -   Pasal 68 -   Pasal 71 -   Pasal 72\n1.  bahwa pelindungan data pribadi merupakan salah satu hak asasi manusia yang merupakan bagian dari pelindungan diri pribadi maka perlu diberikan landasan hukum untuk memberikan keamanan atas data pribadi, berdasarkan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945;\n2.  bahwa pelindungan data pribadi ditujukan untuk menjamin hak warga negara atas pelindungan diri pribadi dan menumbuhkan kesadaran masyarakat serta menjamin pengakuan dan penghormatan atas pentingnya pelindungan data pribadi;\n3.  bahwa pengaturan data pribadi saat ini terdapat di dalam beberapa peraturan perundang-undangan maka untuk meningkatkan efektivitas dalam pelaksanaan pelindungan data pribadi diperlukan pengaturan mengenai pelindungan data pribadi dalam suatu undang-undang;\n4.  bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, huruf b, dan huruf c, perlu membentuk Undang-Undang tentang Pelindungan Data Pribadi;\nPasal 5 ayat (1), Pasal 20, Pasal 28G ayat (1), Pasal 28H ayat (4), dan Pasal 28J Undang-Undang Dasar Negara Republik Indonesia Tahun 1945;\nDengan Persetujuan Bersama\nDEWAN PERWAKILAN RAKYAT REPUBLIK INDONESIA dan PRESIDEN REPUBLIK INDONESIA UNDANG-UNDANG TENTANG PELINDUNGAN DATA PRIBADI.\nCukup jelas.\nCukup jelas.\nHuruf a\nYang dimaksud dengan \"asas pelindungan\" adalah bahwa setiap pemrosesan Data Pribadi dilakukan dengan memberikan pelindungan kepada Subjek Data Pribadi atas Data Pribadinya dan Data Pribadi tersebut agar tidak disalahgunakan.\nHuruf b Yang dimaksud dengan \"asas kepastian hukum\" adalah bahwa setiap pemrosesan Data Pribadi dilakukan berdasarkan landasan hukum untuk mewujudkan Pelindungan Data Pribadi serta segala sesuatu yang mendukung penyelenggaraannya sehingga mendapatkan pengakuan hukum di dalam dan di luar pengadilan.\nHuruf c Yang dimaksud dengan \"asas kepentingan umum\" adalah bahwa dalam menegakkan Pelindungan Data Pribadi harus memperhatikan kepentingan umum atau masyarakat secara luas. Kepentingan umum tersebut antara lain kepentingan penyelenggaraan negara dan pertahanan dan keamanan nasional.\nHuruf d Yang dimaksud dengan \"asas kemanfaatan\" adalah bahwa pengaturan Pelindungan Data Pribadi hams bermanfaat bagi kepentingan nasional, khususnya dalam mewujudkan cita-cita kesejahteraan umum.\nHuruf e Yang dimaksud dengan \"asas kehati-hatian\" adalah bahwa para pihak yang terkait dengan pemrosesan dan pengawasan Data Pribadi hams memperhatikan segenap aspek yang berpotensi mendatangkan kerugian.\nHuruf f Yang dimaksud dengan \"asas keseimbangan\" adalah sebagai upaya Pelindungan Data Pribadi untuk menyeimbangkan antara hak atas Data Pribadi di satu pihak dengan hak negara yang sah berdasarkan kepentingan umum.\nHuruf g Yang dimaksud dengan \"asas pertanggungjawaban\" adalah bahwa semua pihak yang terkait dengan pemrosesan dan pengawasan Data Pribadi bertindak secara bertanggung jawab sehingga mampu menjamin keseimbangan hak dan kewajiban para pihak yang terkait termasuk Subjek Data Pribadi.\nHuruf h Yang dimaksud dengan \"asas kerahasiaan\" adalah bahwa Data Pribadi terlindungi dari pihak yang tidak berhak dan/atau dari kegiatan pemrosesan Data Pribadi yang tidak sah.\nAyat 1\nHuruf a\nData Pribadi yang bersifat spesifik merupakan Data Pribadi yang apabila dalam pemrosesannya dapat mengakibatkan dampak lebih besar kepada Subjek Data Pribadi, antara lain tindakan diskriminasi dan kerugian yang lebih besar Subjek Data Pribadi.\nHuruf b Cukup jelas.\nAyat 2\nHuruf a\nYang dimaksud dengan \"data dan informasi kesehatan\" adalah catatan atau keterangan individu yang berkaitan dengan kesehatan fisik, kesehatan mental, dan/ atau pelayanan kesehatan.\nHuruf b Yang dimaksud dengan \"data biometrik\" adalah data yang berkaitan dengan fisik, fisiologis, atau karakteristik perilaku individu yang memungkinkan"}}],"pack":"id-p03"};
